/** All translations for zizhitongjian ch.028 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起昭陽作噩，盡屠維單閼，凡七年。", literal: "From Zhaoyang Zuoe through Tuwei Shanque; seven years in all.", idiomatic: "From Zhaoyang Zuoe through Tuwei Shanque—seven years in all." },
  { zh: "1春，正月，辛丑，葬孝宣皇帝於杜陵；", literal: "1. In spring, the first month, on xinchou, Emperor Xiao Xuan was buried at Duling;", idiomatic: "1. In spring, the first month, on xinchou, Emperor Xuan was buried at Duling;" },
  { zh: "赦天下。", literal: "a general amnesty was proclaimed.", idiomatic: "the empire was pardoned." },
  { zh: "----2三月，丙午，立皇后王氏，封-{后父}-禁為陽平候。", literal: "----2 In the third month, on bingwu, Empress Wang was installed; Wang -{后父}- Jin was enfeoffed as Marquis of Yangping.", idiomatic: "----2 In the third month, on bingwu, Empress Wang was installed; Wang -{后父}- Jin was enfeoffed as Marquis of Yangping." },
  { zh: "----3以三輔、太常、郡國公田及苑可省者振業貧民；", literal: "----3 Using public fields of the Three Metropolises, the Grand Music Master, commanderies and kingdoms, and parks that could be reduced, to revive the livelihood of poor commoners;", idiomatic: "----3 Public fields of the Three Metropolises, the Grand Music Master, commanderies and kingdoms, and reducible imperial parks were used to revive the livelihood of the poor;" },
  { zh: "貲不滿千錢者，賦貸種、食。", literal: "those whose assets did not reach a thousand cash were granted loans of seed and food.", idiomatic: "those with assets under a thousand cash were lent seed and food." },
  { zh: "----4封外祖父平恩戴侯同產弟子中常侍許嘉為平恩侯。", literal: "----4 The younger brother by the same mother of the emperor's maternal grandfather, Marquis Dai of Ping'en, Palace Attendant Xu Jia, was enfeoffed as Marquis of Ping'en.", idiomatic: "----4 Palace Attendant Xu Jia, younger brother by the same mother of the emperor's maternal grandfather, Marquis Dai of Ping'en, was enfeoffed as Marquis of Ping'en." },
  { zh: "----5夏，六月，以民疾疫，令太官損膳，減樂府員，省苑馬，以振困乏。", literal: "----5 In summer, the sixth month, because the people suffered pestilence, the Grand Provisioner was ordered to reduce meals, Music Bureau staff were cut, park horses were reduced, to relieve the distressed.", idiomatic: "----5 In summer, the sixth month, because pestilence afflicted the people, the court ordered the Grand Provisioner to reduce meals, cut Music Bureau staff, and reduce park horses to relieve the distressed." },
  { zh: "----6秋，九月，關東郡、國十一大水，饑，或人相食；", literal: "----6 In autumn, the ninth month, eleven commanderies and kingdoms east of the Pass suffered great floods; there was famine, and in places men ate one another;", idiomatic: "----6 In autumn, the ninth month, eleven commanderies and kingdoms east of the Pass were inundated; famine followed, and in places men ate one another;" },
  { zh: "轉旁郡錢穀以相救。", literal: "money and grain from neighboring commanderies were transferred to rescue one another.", idiomatic: "money and grain from neighboring commanderies were transferred for mutual relief." },
  { zh: "----7上素聞琅邪王吉、貢禹皆明經潔行，遣使者徵之。", literal: "----7 The emperor had long heard that Wang Ji of Langye and Gong Yu were both versed in the classics with pure conduct; he sent envoys to summon them.", idiomatic: "----7 The emperor had long heard that Wang Ji of Langye and Gong Yu were both versed in the classics and of pure conduct; he sent envoys to summon them." },
  { zh: "吉道病卒。", literal: "Ji died of illness on the road.", idiomatic: "Ji died of illness on the road." },
  { zh: "禹至，拜為諫大夫。", literal: "Yu arrived and was appointed Remonstrating Grandee.", idiomatic: "Yu arrived and was appointed Remonstrating Grandee." },
  { zh: "上數虛已問以政事，禹奏言：「古者人君節儉，什一而稅，無它賦役，故家給人足。", literal: "The emperor repeatedly humbled himself to ask about government affairs. Yu memorialized: \"In antiquity rulers were frugal, taxed one-tenth, and had no other levies or corvée; thus families were provided for and the people had enough.", idiomatic: "The emperor repeatedly humbled himself to ask about government affairs. Yu memorialized: \"In antiquity rulers were frugal, taxed one-tenth, and had no other levies or corvée—families were provided for and the people had enough." },
  { zh: "高祖、孝文、孝景皇帝，宮女不過十餘人，廄馬百餘匹。", literal: "Emperors Gaozu, Xiaowen, and Xiaojing had palace women not exceeding a dozen-odd persons and stable horses a hundred-odd.", idiomatic: "Emperors Gaozu, Wen, and Jing kept no more than a dozen palace women and a hundred-odd stable horses." },
  { zh: "後世爭為奢侈，轉轉益甚；", literal: "Later generations competed in luxury, turning ever more excessive;", idiomatic: "Later generations competed in luxury, each turn more excessive;" },
  { zh: "臣下亦相放效。", literal: "ministers below also imitated one another.", idiomatic: "officials below imitated one another as well." },
  { zh: "臣愚以為如太古難，宜少放古以自節焉。", literal: "Your servant foolishly thinks that matching high antiquity is difficult; it is fitting to release a little toward antiquity and restrain oneself.", idiomatic: "I foolishly think matching high antiquity is difficult; it would be fitting to ease somewhat toward antiquity and restrain oneself." },
  { zh: "方今宮室已定，無可奈何矣；", literal: "Today palaces and halls are already fixed, and nothing can be done;", idiomatic: "Today the palaces are already fixed and nothing can be done about that;" },
  { zh: "其餘盡可減損。", literal: "the rest can all be reduced and cut.", idiomatic: "everything else can still be cut back." },
  { zh: "故時齊三服官，輸物不過十笥；", literal: "In former times Qi's Three Garment Offices supplied goods not exceeding ten bamboo boxes;", idiomatic: "In former times Qi's Three Garment Offices sent no more than ten bamboo boxes of goods;" },
  { zh: "方今齊三服官，作工各數千人，一歲費數巨萬，廄馬食粟將萬匹。", literal: "today Qi's Three Garment Offices have several thousand workers at each workshop, costing tens of millions in one year; stable horses consume grain approaching ten thousand piculs.", idiomatic: "today Qi's Three Garment Offices employ thousands at each workshop, costing tens of millions a year; stable horses consume nearly ten thousand piculs of grain." },
  { zh: "武帝時，又多取好女至數千人，以填後宮。", literal: "Under Emperor Wu, he additionally took fine women numbering in the thousands to fill the rear palace.", idiomatic: "Under Emperor Wu he took thousands of fine women to fill the rear palace." },
  { zh: "及棄天下，多藏金錢、財物，鳥獸、魚鱉凡百九十物；", literal: "When he abandoned the realm, he hoarded much gold, cash, and valuables—birds, beasts, fish, and turtles, one hundred ninety kinds in all;", idiomatic: "When he left the realm he hoarded gold, cash, and valuables—birds, beasts, fish, and turtles, one hundred ninety kinds in all;" },
  { zh: "又皆以後宮女置於園陵。", literal: "moreover he stationed all rear-palace women at park-tombs.", idiomatic: "moreover he stationed rear-palace women at park-tombs." },
  { zh: "至孝宣皇帝時，陛下惡有所言，群臣亦隨故事，甚可痛也！", literal: "At the time of Emperor Xiaoxuan, Your Majesty loathed speaking of such things, yet ministers also followed precedent—how deeply painful!", idiomatic: "At the time of Emperor Xuan, Your Majesty loathed speaking of such things, yet ministers still followed precedent—how painful!" },
  { zh: "故使天下承化，取女皆大過度，諸侯妻妾或至數百人，豪富吏民畜歌者至數十人，是以內多怨女，外多曠夫。", literal: "Thus the realm carried on the transformation: bride-taking everywhere far exceeded measure; feudal lords' wives and concubines sometimes reached hundreds; wealthy officials and commoners kept singers by the dozens—hence within were many resentful women and without many husbandless men.", idiomatic: "Thus the realm carried on the transformation: bride-taking everywhere far exceeded measure; feudal lords' wives and concubines sometimes reached hundreds; wealthy officials and commoners kept dozens of singers—within were many resentful women, without many husbandless men." },
  { zh: "及眾庶葬埋，皆虛地上以實地下。", literal: "Among the masses as well, burials all emptied the above ground to fill the underground.", idiomatic: "Among the common people as well, burials emptied the living world to fill the grave." },
  { zh: "其過自上生，皆在大臣循故事之罪也。", literal: "These excesses arose from above and were all the fault of great ministers who clung to precedent.", idiomatic: "These excesses arose from above and were chiefly the fault of great ministers who clung to precedent." },
  { zh: "唯陛下深察古道，從其儉者。", literal: "Only Your Majesty would deeply examine the ancient Way and follow what is frugal.", idiomatic: "Only Your Majesty would deeply examine the ancient Way and follow what is frugal." },
  { zh: "大減損乘輿服御器物，三分去二；", literal: "Greatly reduce and cut imperial carriages, robes, and implements—remove two parts in three;", idiomatic: "Greatly cut imperial carriages, robes, and implements—remove two parts in three;" },
  { zh: "擇後宮賢者，留二十人，餘悉歸之，及諸陵園女無子者，宜悉遣；", literal: "select the worthy among rear-palace women, retain twenty, return all the rest, and all tomb-park women without sons should be sent out;", idiomatic: "select the worthy among rear-palace women, retain twenty, return the rest, and send out all tomb-park women without sons;" },
  { zh: "廄馬可無過數十匹，獨捨長安城南苑地，以為田獵之囿。", literal: "stable horses need not exceed several dozen; only keep the park south of Chang'an for field and hunt.", idiomatic: "stable horses need not exceed several dozen; only keep the park south of Chang'an for hunting." },
  { zh: "方今天下饑饉，可無大自損減以救之稱天意乎！", literal: "Today the realm suffers famine—can we not greatly reduce ourselves to deliver relief and match Heaven's intent!", idiomatic: "Today the realm suffers famine—can we not greatly reduce ourselves to deliver relief and match Heaven's intent!" },
  { zh: "天生聖人，蓋為萬民，非獨使自娛樂而已也。", literal: "Heaven born the sage to be for the myriad people—not merely for his own pleasure.", idiomatic: "Heaven born the sage for the myriad people—not merely for his own pleasure." },
  { zh: "」天子納善其言，下詔，令諸宮館希御幸者勿繕治；", literal: "\" The Son of Heaven accepted his good words and issued an edict: palace residences rarely favored by the emperor should not be repaired;", idiomatic: "\" The emperor accepted his counsel and issued an edict: palace residences rarely visited by the emperor should not be repaired;" },
  { zh: "太僕減穀食馬；", literal: "the Grand Coachman reduced grain for horses;", idiomatic: "the Grand Coachman reduced grain for horses;" },
  { zh: "水衡省肉食獸。", literal: "the Office of Water and Parks cut meat-eating beasts.", idiomatic: "the Office of Water and Parks cut meat-eating beasts." },
  { zh: ":臣光曰：忠臣之事君也，責其所難，則其易者不勞而正；", literal: ": Your servant Guang says: When loyal ministers serve their ruler, they press what is difficult; then what is easy is corrected without labor;", idiomatic: ": Your servant Guang says: When loyal ministers serve their ruler, they press what is difficult; then what is easy is corrected without labor;" },
  { zh: "補其所短，則其長者不勸而遂。", literal: "they mend what is short; then what is long advances without exhortation.", idiomatic: "they mend what is short; then what is long advances without exhortation." },
  { zh: "孝元踐位之初，虛心以問禹，禹宜先其所急，後其所緩。", literal: "At the beginning of Emperor Xiaoyuan's accession, he humbly asked Yu; Yu should have put first what was urgent and afterward what could wait.", idiomatic: "At the beginning of Emperor Yuan's accession, he humbly asked Yu; Yu should have put first what was urgent and afterward what could wait." },
  { zh: "然則優遊不斷，讒佞用權，當時之大患也，而禹不以為言；", literal: "Yet lenient delay without decision, slanderers and flatterers wielding power—the great affliction of the time—and Yu did not speak of it;", idiomatic: "Yet lenient delay without decision and slanderers and flatterers wielding power were the great afflictions of the time, yet Yu did not speak of them;" },
  { zh: "恭謹節儉，孝元之素志也，而禹孜孜而言之，何哉！", literal: "respectful caution and frugality were Emperor Xiaoyuan's constant aim, yet Yu spoke of them tirelessly—why!", idiomatic: "respectful caution and frugality were Emperor Yuan's constant aim, yet Yu spoke of them tirelessly—why!" },
  { zh: "使禹之智足不以知，烏得為賢！", literal: "If Yu's wisdom sufficed yet he did not know, how could he be called worthy!", idiomatic: "If Yu's wisdom sufficed yet he did not know, how could he be called worthy!" },
  { zh: "知而不言，為罪愈大矣！", literal: "To know and not speak—the offense is all the greater!", idiomatic: "To know and not speak—the offense is all the greater!" },
  { zh: "----8匈奴呼韓邪單于復上書，言民眾困乏。", literal: "----8 The Xiongnu chanyu Huhanye again submitted a memorial saying his people were distressed and depleted.", idiomatic: "----8 The Xiongnu chanyu Huhanye again submitted a memorial saying his people were distressed and depleted." },
  { zh: "詔雲中、五原郡轉穀二萬斛以給之。", literal: "An edict ordered Yunzhong and Wuyuan commanderies to transfer twenty thousand hu of grain to supply him.", idiomatic: "An edict ordered Yunzhong and Wuyuan commanderies to transfer twenty thousand hu of grain to supply him." },
  { zh: "----9是歲，初置戊己校尉，使屯田車師故地。", literal: "----9 That year, the Wuji Colonel was first established to garrison and farm the former territory of Cheshi.", idiomatic: "----9 That year the Wuji Colonel was first established to garrison and farm the former territory of Cheshi." },
  { zh: "1春，正月，上行幸甘泉，郊泰畤。", literal: "1. In spring, the first month, the emperor traveled in favor to Sweet Springs and sacrificed at the border to the Great Altar.", idiomatic: "1. In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar." },
  { zh: "樂陵侯史高以外屬領尚書事，前將軍蕭望之、光祿大夫周堪為之副。", literal: "Yue Ling Marquis Shi Gao, as maternal kin, headed Secretariat affairs; former General Xiao Wangzhi and Household Gentleman Zhou Kan served as his deputies.", idiomatic: "Yue Ling Marquis Shi Gao, as maternal kin, headed Secretariat affairs; former General Xiao Wangzhi and Household Gentleman Zhou Kan served as his deputies." },
  { zh: "望之名儒，與堪皆以師傅舊恩，天子任之，數宴見，言治亂，陳王事。", literal: "Wangzhi was a renowned classicist; both he and Kan, through old favor as tutors, were trusted by the Son of Heaven, often received at banquets, spoke of order and disorder, and laid out royal affairs.", idiomatic: "Wangzhi was a renowned classicist; both he and Kan, through old ties as tutors, were trusted by the emperor, often dined with him, discussed order and disorder, and laid out royal affairs." },
  { zh: "望之選白宗室明經有行散騎、諫大夫劉更生給事中，與侍中金敞並拾遺左右。", literal: "Wangzhi nominated and reported Liu Gengsheng of the imperial clan, versed in the classics with conduct, as Cavalier Attendant and Remonstrating Grandee in the Palace Secretariat, together with Palace Attendant Jin Chang picking up what was neglected at the ruler's side.", idiomatic: "Wangzhi nominated Liu Gengsheng of the imperial clan, versed in the classics and of good conduct, as Cavalier Attendant and Remonstrating Grandee in the Palace Secretariat; he and Palace Attendant Jin Chang picked up what was neglected at the emperor's side." },
  { zh: "四人同心謀議，勸導上以古制，多所欲匡正；", literal: "The four men united in counsel, urging the ruler toward ancient institutions and wanting much to correct abuses;", idiomatic: "The four men united in counsel, urging the emperor toward ancient institutions and wanting much to correct abuses;" },
  { zh: "上甚鄉納之。", literal: "the emperor greatly inclined to accept them.", idiomatic: "the emperor greatly inclined to accept them." },
  { zh: "史高充位而已，由此與望之有隙。", literal: "Shi Gao merely filled a post; from this he bore a rift with Wangzhi.", idiomatic: "Shi Gao merely filled a post; from this he bore a rift with Wangzhi." },
  { zh: "中書令弘恭、僕射石顯，自宣帝時久典樞機，明習文法；", literal: "Palace Secretariat Director Hong Gong and Vice Director Shi Xian, from Emperor Xuan's time, had long held the pivot of power and were skilled in written law;", idiomatic: "Palace Secretariat Director Hong Gong and Vice Director Shi Xian had long held the pivot of power from Emperor Xuan's time and were skilled in written law;" },
  { zh: "帝即位多疾，以顯久典事，中人無外黨，精專可信任，遂委以政，事無小大，因顯白決，貴幸傾朝，百僚皆敬事顯。", literal: "when the emperor took the throne he was often ill; because Xian had long managed affairs and the inner attendants had no external faction and were dedicated and trustworthy, government was entrusted to him—matters great or small were decided as Xian reported upward; honored and favored, he dominated the court, and all officials honored and served Xian.", idiomatic: "when the emperor took the throne he was often ill; because Xian had long managed affairs and the inner attendants had no external faction and were dedicated and trustworthy, he entrusted him with government—matters great or small were decided as Xian reported upward; honored and favored, he dominated the court, and all officials honored and served Xian." },
  { zh: "顯為人巧慧習事，能深得人主微指，內深賊，持詭辯，以中傷人，忤恨睚眥，輒被以危法；", literal: "Xian as a man was clever and practiced in affairs, able to grasp the ruler's subtle intent; inwardly deeply malicious, he wielded deceptive argument to strike at men; for the smallest grudge he would cloak them in deadly law;", idiomatic: "Xian was clever and practiced in affairs, able to grasp the ruler's subtle intent; inwardly deeply malicious, he wielded deceptive argument to strike at men; for the smallest grudge he would cloak opponents in deadly law;" },
  { zh: "亦與車騎將軍高為表裡，議論常獨持故事，不從望之等。", literal: "he also worked hand in glove with General of Chariots and Cavalry Gao; in discussion they usually held alone to precedent and did not follow Wangzhi and the others.", idiomatic: "he also worked hand in glove with General of Chariots and Cavalry Gao; in discussion they usually held alone to precedent and did not follow Wangzhi and the others." },
  { zh: "望之等患苦許、史放縱，又疾恭、顯擅權，建白以為：「中書政本，國家樞機，宜以通明公正處之。", literal: "Wangzhi and his circle were distressed at Xu and Shi clans' license and hated that Gong and Xian monopolized power; they memorialized: \"The Secretariat is the root of government and the state's pivot; it should be run with luminous fairness.", idiomatic: "Wangzhi and his circle were distressed at the Xu and Shi clans' license and hated that Gong and Xian monopolized power; they memorialized: \"The Secretariat is the root of government and the state's pivot; it should be run with luminous fairness." },
  { zh: "武帝游宴後庭，故用宦者，非古制也。", literal: "When Emperor Wu held banquets in the rear court he employed eunuchs—this is not the ancient system.", idiomatic: "When Emperor Wu held banquets in the rear court he employed eunuchs—this is not the ancient system." },
  { zh: "宜罷中書宦官，應古不近刑人之義。", literal: "Eunuchs in the Secretariat should be abolished, in keeping with antiquity's rule that those near punishment should not hold power.", idiomatic: "Eunuchs in the Secretariat should be abolished, in keeping with antiquity's rule that those near punishment should not hold power." },
  { zh: "」由是大與高、恭、顯忤。", literal: "\" From this they sharply clashed with Gao, Gong, and Xian.", idiomatic: "\" From this they sharply clashed with Gao, Gong, and Xian." },
  { zh: "上初即位，謙讓，重改作，議久不定，出劉更生為宗正。", literal: "The emperor, newly enthroned, was modest and reluctant and regarded reorganization as weighty; the debate long went unsettled, and Liu Gengsheng was sent out as Director of the Imperial Clan.", idiomatic: "The emperor, newly enthroned, was modest and reluctant and regarded reorganization as weighty; the debate long went unsettled, and Liu Gengsheng was sent out as Director of the Imperial Clan." },
  { zh: "望之、堪數薦名儒、茂材以備諫官，會稽鄭朋陰欲附望之，上書言車騎將軍高遣客為奸利郡國，及言許、史弟子罪過。", literal: "Wangzhi and Kan repeatedly recommended renowned classicists and exceptional talent for remonstrance offices. Kuaiji's Zheng Peng secretly wished to attach himself to Wangzhi and memorialized that General of Chariots and Cavalry Gao's clients did illicit profit in commanderies and kingdoms, and cited crimes of Xu and Shi clan youths.", idiomatic: "Wangzhi and Kan repeatedly recommended renowned classicists and exceptional talent for remonstrance offices. Kuaiji's Zheng Peng secretly wished to attach himself to Wangzhi and memorialized that General of Chariots and Cavalry Gao's clients did illicit profit in commanderies and kingdoms, and cited crimes of Xu and Shi clan youths." },
  { zh: "章視周堪，堪白：「令朋待詔金馬門。", literal: "The memorial was shown to Zhou Kan; Kan reported: \"Let Peng await summons at the Golden Horse Gate.", idiomatic: "The memorial was shown to Zhou Kan; Kan reported: \"Let Peng await summons at the Golden Horse Gate." },
  { zh: "」朋奏記望之曰：「今將軍規模，-{云}-若管、晏而休，遂行日昃，至周、召乃留乎？", literal: "\" Peng submitted a memorial-note to Wangzhi, saying: \"Now the general's scope—-{云}- if like Guan Zhong and Yan Ying you then stop, will you halt at sunset only when you reach the Duke of Zhou and Duke of Shao?", idiomatic: "\" Peng submitted a memorial-note to Wangzhi, saying: \"Now the general's scope—-{云}- if like Guan Zhong and Yan Ying you then stop, will you halt at sunset only when you reach the Duke of Zhou and Duke of Shao?" },
  { zh: "若管、晏而休，則下走將歸延陵之皋，沒齒而已矣。", literal: "If you stop at Guan and Yan, your subordinates below will go home to Yanling's shore and till to the end of their days.", idiomatic: "If you stop at Guan and Yan, your subordinates below will go home to Yanling's shore and till to the end of their days." },
  { zh: "如將軍興周、召之遺業，親日昃之兼聽，則下走其庶幾願竭區區奉萬分之一！", literal: "But if the general takes up the legacy of the Duke of Zhou and Duke of Shao, personally attending from morning to night with broad hearing, then your subordinates below would scarcely dare hope to exhaust their petty strength for even one part in ten thousand!", idiomatic: "But if the general takes up the legacy of the Duke of Zhou and Duke of Shao, personally attending from morning to night with broad hearing, then your subordinates below would scarcely dare hope to exhaust their petty strength for even one part in ten thousand!" },
  { zh: "」望之始見朋，接待以意；", literal: "\" Wangzhi at first received Peng with attention;", idiomatic: "\" Wangzhi at first received Peng with attention;" },
  { zh: "後知其傾邪，絕不與通。", literal: "later learning he was crooked, he cut him off entirely.", idiomatic: "later learning he was crooked, he cut him off entirely." },
  { zh: "朋，楚士，怨恨，更求入許、史，推所言許、史事，曰：「皆周堪、劉更生教我；", literal: "Peng, a man of Chu, bore resentment, sought entry among Xu and Shi, and pushed claims about Xu and Shi affairs, saying: \"All of it Zhou Kan and Liu Gengsheng taught me;", idiomatic: "Peng, a man of Chu, bore resentment, sought entry among Xu and Shi, and pushed claims about Xu and Shi affairs, saying: \"All of it Zhou Kan and Liu Gengsheng taught me;" },
  { zh: "我關東人，何以知此！", literal: "I am a man east of the Pass—how would I know this!", idiomatic: "I am a man east of the Pass—how would I know this!" },
  { zh: "」於是侍中許章白見朋。", literal: "\" Thereupon Palace Attendant Xu Zhang had Peng brought to audience.", idiomatic: "\" Thereupon Palace Attendant Xu Zhang had Peng brought to audience." },
  { zh: "朋出，揚言曰：「我見言前將軍小過五，大罪一。", literal: "Peng came out and proclaimed: \"I told of five small faults and one great crime of the former general.", idiomatic: "Peng came out and proclaimed: \"I told of five small faults and one great crime of the former general." },
  { zh: "」待詔華龍行污穢，欲入堪等，堪等不納，亦與朋相結。", literal: "\" Attendant Hua Long practiced filth and wanted to join Kan's faction; they would not take him in, yet he allied with Peng as well.", idiomatic: "\" Attendant Hua Long practiced filth and wanted to join Kan's faction; they would not take him in, yet he allied with Peng as well." },
  { zh: "恭、顯令二人告望之等謀欲罷車騎將軍，疏退許、史狀，候望之出休日，令朋、龍上之。", literal: "Gong and Xian had the two men accuse Wangzhi and company of plotting to remove General of Chariots and Cavalry Gao and of memorializing to push aside Xu and Shi; they waited for Wangzhi's day off and had Peng and Long submit it.", idiomatic: "Gong and Xian had the two men accuse Wangzhi and company of plotting to remove General of Chariots and Cavalry Gao and of memorializing to push aside Xu and Shi; they waited for Wangzhi's day off and had Peng and Long submit it." },
  { zh: "事下弘恭問狀，望之對曰：「外戚在位多奢淫，欲以匡正國家，非為邪也。", literal: "The matter went down to Hong Gong for inquiry. Wangzhi answered: \"The outer kin in office are mostly extravagant—the aim is to correct the state, not to do evil.", idiomatic: "The matter went down to Hong Gong for inquiry. Wangzhi answered: \"The outer kin in office are mostly extravagant—the aim is to correct the state, not to do evil." },
  { zh: "」恭、顯奏：「望之、堪、更生朋黨相稱舉，數譖訴大臣，毀離親戚，欲以專擅權勢。", literal: "\" Gong and Xian memorialized: \"Wangzhi, Kan, and Gengsheng formed a faction praising one another, repeatedly slandering great ministers, tearing apart relatives, wishing to monopolize power.", idiomatic: "\" Gong and Xian memorialized: \"Wangzhi, Kan, and Gengsheng formed a faction praising one another, repeatedly slandering great ministers, tearing apart relatives, wishing to monopolize power." },
  { zh: "為臣不忠，誣上不道，請謁者召致廷尉。", literal: "As ministers unloyal, deceiving the throne and impious, they ask that the courier summon them to the Minister of Justice.", idiomatic: "As ministers unloyal, deceiving the throne and impious, they ask that the courier summon them to the Minister of Justice." },
  { zh: "」時上初即位，不省召致廷尉為下獄也，可其奏。", literal: "\" At the time the emperor, newly enthroned, did not understand that \"summon to the Minister of Justice\" meant imprisonment and approved the memorial.", idiomatic: "\" At the time the emperor, newly enthroned, did not understand that \"summon to the Minister of Justice\" meant imprisonment and approved the memorial." },
  { zh: "後上召堪、更生，曰：「繫獄。", literal: "Later the emperor summoned Kan and Gengsheng and said: \"Imprisoned.", idiomatic: "Later the emperor summoned Kan and Gengsheng and said: \"Imprisoned." },
  { zh: "」上大驚曰：「非但廷尉問邪！", literal: "\" The emperor was greatly alarmed: \"Not merely inquiry by the Minister of Justice!", idiomatic: "\" The emperor was greatly alarmed: \"Not merely inquiry by the Minister of Justice!" },
  { zh: "」以責恭、顯，皆叩頭謝。", literal: "\" He reproached Gong and Xian, who all knocked their heads in apology.", idiomatic: "\" He reproached Gong and Xian, who all knocked their heads in apology." },
  { zh: "上曰：「令出視事。", literal: "The emperor said: \"Let them go out and resume duties.", idiomatic: "The emperor said: \"Let them go out and resume duties." },
  { zh: "」恭、顯因使史高言：「上新即位，未以德化聞於天下，而先驗師傅。", literal: "\" Gong and Xian then had Shi Gao speak: \"Your Majesty is newly enthroned and has not yet made your virtue heard throughout the realm, yet you first try your tutors.", idiomatic: "\" Gong and Xian then had Shi Gao speak: \"Your Majesty is newly enthroned and has not yet made your virtue heard throughout the realm, yet you first try your tutors." },
  { zh: "既下九卿、大夫獄，宜因決免。", literal: "They are already down in the Nine Ministers and Grandees' prison—it is fitting to decide and dismiss them.", idiomatic: "They are already down in the Nine Ministers and Grandees' prison—it is fitting to decide and dismiss them." },
  { zh: "」於是制詔丞相、御史：「前將軍望之，傅朕八年，無它罪過。", literal: "\" Thereupon an edict to Chancellor and Censor: \"Former general Wangzhi tutored Us eight years without other fault.", idiomatic: "\" Thereupon an edict to Chancellor and Censor: \"Former general Wangzhi tutored Us eight years without other fault." },
  { zh: "今事久遠，識忘難明，其赦望之罪，收前將軍、光祿勳印綬；", literal: "The matter is long past and memory hard to clear—pardon Wangzhi's crime and take back the seals of Former General and Household Gentleman;", idiomatic: "The matter is long past and memory hard to clear—pardon Wangzhi's crime and take back the seals of Former General and Household Gentleman;" },
  { zh: "及堪、更生皆免為庶人。", literal: "Kan and Gengsheng are all demoted to commoners.\"", idiomatic: "Kan and Gengsheng are all demoted to commoners.\"" },
  { zh: "」----2二月，丁巳，立弟竟為清河王。", literal: "\" ----2 In the second month, on dingsi, the emperor's younger brother Jing was installed as King of Qinghe.", idiomatic: "\" ----2 In the second month, on dingsi, the emperor's younger brother Jing was installed as King of Qinghe." },
  { zh: "----3戊午，隴西地震，敗城郭、屋室，壓殺人眾。", literal: "----3 On wuwu, Longxi suffered an earthquake that destroyed walls and houses and crushed many to death.", idiomatic: "----3 On wuwu, Longxi suffered an earthquake that destroyed walls and houses and crushed many to death." },
  { zh: "----4三月，立廣陵厲王子霸為王。", literal: "----4 In the third month, the son of the deposed King of Guangling, Ba, was installed as king.", idiomatic: "----4 In the third month, the son of the deposed King of Guangling, Ba, was installed as king." },
  { zh: "----5詔罷黃門乘輿狗馬，水衡禁囿、宜春下苑、少府佽飛外池、嚴籞池田假與貧民。", literal: "----5 An edict abolished Yellow Gate carriage dogs and horses; the Offices of Water and Parks, Yichun Lower Park, Lesser Treasury flying outer pools, and strict park pool fields were rented to poor commoners.", idiomatic: "----5 An edict abolished Yellow Gate carriage dogs and horses; the Offices of Water and Parks, Yichun Lower Park, Lesser Treasury flying outer pools, and strict park pool fields were rented to poor commoners." },
  { zh: "又詔赦天下，舉茂材異等、直言極諫之士。", literal: "Another edict pardoned the realm and raised exceptional talent of unusual grade and men of blunt remonstrance.", idiomatic: "Another edict pardoned the realm and raised exceptional talent of unusual grade and men of blunt remonstrance." },
  { zh: "----6夏，四月，丁巳，立子驁為皇太子。", literal: "----6 In summer, the fourth month, on dingsi, son Ao was installed as Imperial Heir Apparent.", idiomatic: "----6 In summer, the fourth month, on dingsi, son Ao was installed as crown prince." },
  { zh: "待詔鄭朋薦太原太守張敞，先帝名臣，宜傅輔皇太子。", literal: "Attendant Zheng Peng recommended Taiyuan governor Zhang Chang, an esteemed minister of the former emperor, as fit to tutor and assist the Imperial Heir Apparent.", idiomatic: "Attendant Zheng Peng recommended Taiyuan governor Zhang Chang, an esteemed minister of the former emperor, as fit to tutor and assist the crown prince." },
  { zh: "上以問蕭望之，望之以為敞能吏，任治煩亂，材輕，非師傅之器。", literal: "The emperor asked Xiao Wangzhi; Wangzhi thought Chang a capable official for troubled governance but light in talent—not material for a tutor.", idiomatic: "The emperor asked Xiao Wangzhi; Wangzhi thought Chang a capable official for troubled governance but light in talent—not material for a tutor." },
  { zh: "天子使使者徵敞，欲以為左馮翊，會病卒。", literal: "The Son of Heaven sent a courier to summon Chang, wishing to make him Left Governor of Feng, but he died of illness en route.", idiomatic: "The emperor sent a courier to summon Chang, wishing to make him Left Governor of Feng, but he died of illness en route." },
  { zh: "----7詔賜蕭望之爵關內侯，給事中，朝朔望。", literal: "----7 An edict granted Xiao Wangzhi the rank of Marquis within the Passes, appointment in the Palace Secretariat, and attendance on the first and fifteenth of the month.", idiomatic: "----7 An edict granted Xiao Wangzhi the rank of Marquis within the Passes, appointment in the Palace Secretariat, and attendance on the first and fifteenth of the month." },
  { zh: "----8關東饑，齊地人相食。", literal: "----8 East of the Pass suffered famine; in Qi territory people ate one another.", idiomatic: "----8 East of the Pass suffered famine; in Qi territory people ate one another." },
  { zh: "----9秋，七月，己酉，地復震。", literal: "----9 Autumn, seventh month, day jiyou: the earth quaked again.", idiomatic: "----9 In autumn, the seventh month, on day jiyou, the earth quaked again." },
  { zh: "----10上復征周堪、劉更生，欲以為諫大夫；", literal: "----10 The emperor again summoned Zhou Kan and Liu Gengsheng, wishing to make them Remonstrance Grandees;", idiomatic: "----10 The emperor again summoned Zhou Kan and Liu Gengsheng, wishing to make them Remonstrance Grandees;" },
  { zh: "弘恭、石顯白，皆以為中郎。", literal: "Hong Gong and Shi Xian reported, and all were made Gentlemen of the Palace.", idiomatic: "Hong Gong and Shi Xian reported against it, and all were made Gentlemen of the Palace instead." },
  { zh: "上器重蕭望之不已，欲倚以為相；", literal: "The emperor valued Xiao Wangzhi without cease and wished to rely on him as chancellor;", idiomatic: "The emperor valued Xiao Wangzhi without cease and wished to rely on him as chancellor;" },
  { zh: "恭、顯及許、史子弟、侍中、諸曹皆側目於望之等。", literal: "Gong, Xian, and the Xu and Shi clans' sons and younger brothers, palace attendants, and the various bureaus all glared sidelong at Wangzhi and the rest.", idiomatic: "Gong, Xian, and the Xu and Shi clans' sons and younger brothers, palace attendants, and the various bureaus all glared sidelong at Wangzhi and his circle." },
  { zh: "更生乃使其外親上變事，言「地震殆為恭等，不為三獨夫動。", literal: "Gengsheng then had a maternal relative submit a report of irregularity, saying \"The earthquake was probably for Gong and the rest, not moved by the three lone men.", idiomatic: "Gengsheng then had a maternal relative submit a report of irregularity, saying, \"The earthquake was probably on account of Gong and the rest, not stirred by the three lone men." },
  { zh: "臣愚以為宜退恭、顯以章蔽善之罰，進望之等以通賢者之路。", literal: "Your servant is foolish and thinks one ought to dismiss Gong and Xian to make clear the punishment for screening out the good, and advance Wangzhi and the rest to open the road for the worthy.", idiomatic: "Your servant thinks one ought to dismiss Gong and Xian to make clear the punishment for screening out the good, and advance Wangzhi and the rest to open the road for the worthy." },
  { zh: "如此，則太平之門開，災異之原塞矣。", literal: "If so, then the gate of great peace would open and the source of portents and anomalies would be blocked.", idiomatic: "If so, the gate of great peace would open and the source of portents and anomalies would be blocked." },
  { zh: "」書奏，恭、顯疑其更生所為，白請考奸詐，辭果服；", literal: "\" When the memorial was submitted, Gong and Xian suspected Gengsheng had done it and reported requesting investigation for treachery and fraud; under interrogation the words indeed matched;", idiomatic: "\" When the memorial was submitted, Gong and Xian suspected Gengsheng had done it and requested investigation for treachery and fraud; under interrogation the confession indeed matched;" },
  { zh: "遂逮更生繫獄，免為庶人。", literal: "Gengsheng was thereupon arrested and imprisoned, and dismissed as a commoner.", idiomatic: "Gengsheng was thereupon arrested and imprisoned, and dismissed as a commoner." },
  { zh: "會望之子散騎、中郎人及亦上書訟望之前事，事下有司，復奏：「望之前所坐明白，無譖訴者，而教子上書，稱引亡辜之詩，失大臣體，不敬，請逮捕。", literal: "It happened that Wangzhi's son Sanqi and Gentleman of the Palace Ren Ji also submitted a memorial suing over Wangzhi's former case; the matter was sent down to the officials, who again memorialized: \"Wangzhi's former offense was clear and there was no false accusation, yet he taught his son to submit a memorial, citing poems of the guiltless dead—losing a great minister's bearing, disrespectful; we request arrest.", idiomatic: "It happened that Wangzhi's son Sanqi and Gentleman of the Palace Ren Ji also memorialized suing over Wangzhi's former case; the matter was sent to the officials, who again reported, \"Wangzhi's former offense was clear and there was no false accusation, yet he taught his son to submit a memorial citing poems of the guiltless dead—losing a great minister's bearing and showing disrespect; we request arrest." },
  { zh: "」弘恭、石顯等知望之素高節，不詘辱，建白：「望之前幸得不坐，復賜爵邑，不悔過服罪，深懷怨望，教子上書，歸非於上，自以托師傅，終必不坐，非頗屈望之於牢獄，塞其怏怏心，則聖朝無以施恩厚。", literal: "\" Hong Gong, Shi Xian, and the rest knew Wangzhi by nature had lofty integrity and would not submit to humiliation, and proposed: \"Wangzhi before fortunately escaped punishment, again received noble rank and fief, did not repent and accept guilt, deeply harbored resentment, taught his son to submit a memorial, and attributed blame to the emperor—trusting that as one who relied on the imperial tutor he would in the end certainly not be punished. Unless Wangzhi is somewhat bent in prison to stop up his resentful heart, the sagely court has no way to bestow generous grace.", idiomatic: "\" Hong Gong, Shi Xian, and the rest knew Wangzhi by nature had lofty integrity and would not submit to humiliation, and proposed, \"Wangzhi before fortunately escaped punishment and again received noble rank and fief, yet did not repent and accept guilt, deeply harbored resentment, taught his son to memorialize, and attributed blame to the emperor—trusting that as imperial tutor he would in the end certainly not be punished. Unless Wangzhi is somewhat bent in prison to stop up his resentful heart, the sagely court has no way to bestow generous grace." },
  { zh: "」上曰：「蕭太傅素剛，安肯就吏！", literal: "\" The emperor said: \"Grand Tutor Xiao is by nature firm—how would he consent to go to the officials!", idiomatic: "\" The emperor said, \"Grand Tutor Xiao is by nature firm—how would he consent to go to the officials!" },
  { zh: "」顯等曰：「人命至重，望之所坐，語言薄罪，必無所憂。", literal: "\" Xian and the rest said: \"Human life is utmostly weighty; what Wangzhi sits in is a slight offense of words—he will certainly have no worry.", idiomatic: "\" Xian and the rest said, \"Human life is utmostly weighty; what Wangzhi sits in is a slight offense of words—he will certainly have no worry." },
  { zh: "」上乃可其奏。", literal: "\" The emperor thereupon approved their memorial.", idiomatic: "\" The emperor thereupon approved their memorial." },
  { zh: "冬，十二月，顯等封詔以付謁者，敕令召望之手付。", literal: "Winter, twelfth month: Xian and the rest sealed the edict and gave it to the usher, ordering him to summon Wangzhi and hand it to him in person.", idiomatic: "In winter, the twelfth month, Xian and the rest sealed the edict and gave it to the usher, ordering him to summon Wangzhi and hand it to him in person." },
  { zh: "因令太常急發執金吾車騎馳圍其第。", literal: "They then ordered the Grand Minister of Ceremonies urgently to dispatch the Commandant of the Metropolitan Area's chariots and horsemen to gallop and surround his residence.", idiomatic: "They then ordered the Grand Minister of Ceremonies urgently to dispatch the Commandant of the Metropolitan Area's chariots and horsemen to gallop and surround his residence." },
  { zh: "使者至，召望之。", literal: "When the envoy arrived, he summoned Wangzhi.", idiomatic: "When the envoy arrived, he summoned Wangzhi." },
  { zh: "望之以問門下生魯國朱雲，雲者，好節士，勸望之自裁。", literal: "Wangzhi questioned his gate student Zhu Yun of Lu about it; Yun was one who loved men of integrity and urged Wangzhi to take his own life.", idiomatic: "Wangzhi asked his gate student Zhu Yun of Lu about it; Yun, who loved men of integrity, urged Wangzhi to take his own life." },
  { zh: "於是望之仰天歎曰：「吾嘗備位將相，年逾六十矣，老入牢獄，苟求生活，不亦鄙乎！", literal: "Thereupon Wangzhi looked up to heaven and sighed, saying: \"I once filled the rank of general and minister; I am past sixty. To grow old entering prison and basely seeking to live—would that not be base!", idiomatic: "Thereupon Wangzhi looked up to heaven and sighed, \"I once filled the rank of general and minister; I am past sixty. To grow old entering prison and basely seeking to live—would that not be base!" },
  { zh: "」字謂雲曰：「游，趣和藥來，無久留我死！", literal: "\" He addressed Yun by his style name, saying: \"You—hurry and bring the poisoned draught; do not long detain my death!", idiomatic: "\" He addressed Yun by his style name, saying, \"You—hurry and bring the poisoned draught; do not long detain my death!" },
  { zh: "」竟飲鳩自殺。", literal: "\" In the end he drank bane and killed himself.", idiomatic: "\" In the end he drank bane and killed himself." },
  { zh: "天子聞之驚，拊手曰：「曩固疑其不就牢獄，果然殺吾賢傅！", literal: "The Son of Heaven, hearing it, was startled and clapped his hands, saying: \"Before I indeed doubted he would not go to prison—he has truly killed my worthy tutor!", idiomatic: "The emperor, hearing it, was startled and clapped his hands, saying, \"Before I indeed doubted he would not go to prison—he has truly killed my worthy tutor!" },
  { zh: "」是時，太官方上晝食，上乃卻食，為之涕泣，哀動左右。", literal: "\" At that time the Grand Steward was just serving the midday meal; the emperor thereupon pushed the meal away, wept tears for him, and his grief moved those at his side.", idiomatic: "\" At that time the Grand Steward was just serving the midday meal; the emperor pushed the meal away, wept for him, and his grief moved those at his side." },
  { zh: "於是召顯等責問；", literal: "Thereupon he summoned Xian and the rest to rebuke and question them;", idiomatic: "Thereupon he summoned Xian and the rest to rebuke and question them;" },
  { zh: "以議不詳，皆免冠謝，良久然後已。", literal: "because their deliberation had not been thorough, all removed their caps and apologized; only after a long while did he stop.", idiomatic: "because their deliberation had not been thorough, all removed their caps and apologized; only after a long while did he stop." },
  { zh: "上追念望之不忘，每歲時遣使者祠祭望之塚，終帝之世。", literal: "The emperor, recalling Wangzhi without forgetting, every year at the seasons sent envoys to sacrifice at Wangzhi's tomb—throughout the emperor's reign.", idiomatic: "The emperor, recalling Wangzhi without forgetting, every year at the seasons sent envoys to sacrifice at Wangzhi's tomb throughout his reign." },
  { zh: ":臣光曰：甚矣孝元之為君，易欺而難寤也！", literal: ": Your servant Guang says: How extreme was Emperor Xiao Yuan as ruler—easy to deceive and hard to awaken!", idiomatic: ": Your servant Guang says: How extreme was Emperor Yuan as ruler—easy to deceive and hard to awaken!" },
  { zh: "夫恭、顯之譖訴望之，其邪說詭計，誠有所不能辨也。", literal: "As for Gong and Xian's false accusations against Wangzhi, their perverse words and deceitful schemes—there truly were things he could not distinguish.", idiomatic: "As for Gong and Xian's false accusations against Wangzhi, their perverse words and deceitful schemes—there truly were things he could not distinguish." },
  { zh: "至於始疑望之不肯就獄，恭、顯以為必無憂。", literal: "As for his first doubting that Wangzhi would not consent to go to prison, and Gong and Xian thinking he would certainly have no worry—", idiomatic: "As for his first doubting that Wangzhi would not consent to go to prison, and Gong and Xian thinking he would certainly have no worry—" },
  { zh: "已而果自殺，則恭、顯之欺亦明矣。", literal: "yet afterward he indeed killed himself—then Gong and Xian's deception was also clear.", idiomatic: "yet afterward he indeed killed himself—then Gong and Xian's deception was also clear." },
  { zh: "在中智之君，孰不感動奮發以厎邪臣之罰！", literal: "In a ruler of middling wisdom, who would not be moved and roused to apply the punishment to wicked ministers!", idiomatic: "In a ruler of middling wisdom, who would not be moved and roused to punish wicked ministers!" },
  { zh: "孝元則不然。", literal: "Emperor Xiao Yuan was not so.", idiomatic: "Emperor Yuan was not so." },
  { zh: "雖涕泣不食以傷望之，而終不能誅恭、顯，才得其免冠謝而已。", literal: "Though he wept, refused food, and grieved for Wangzhi, in the end he could not execute Gong and Xian—he only got their removing caps and apologizing, and that was all.", idiomatic: "Though he wept, refused food, and grieved for Wangzhi, in the end he could not execute Gong and Xian—he only got them to remove their caps and apologize, and that was all." },
  { zh: "如此，則奸臣安所懲乎！", literal: "If so, where would wicked ministers be punished!", idiomatic: "If so, where would wicked ministers be punished!" },
  { zh: "是使恭、顯得肆其邪心而無復忌憚者也。", literal: "This was what let Gong and Xian unleash their wicked hearts without further fear or restraint.", idiomatic: "This was what let Gong and Xian unleash their wicked hearts without further fear or restraint." },
  { zh: "----11是歲，弘恭病死，石顯為中書令。", literal: "----11 That year Hong Gong died of illness; Shi Xian became Director of the Palace Secretariat.", idiomatic: "----11 That year Hong Gong died of illness; Shi Xian became Director of the Palace Secretariat." },
  { zh: "----12初，武帝滅南越，開置珠崖、儋耳郡，在海中洲上，吏卒皆中國人，多侵陵之。", literal: "----12 Initially, when Emperor Wu destroyed Nanyue, he opened and established Zhuya and Dan'er commanderies on islands in the sea; clerks and soldiers were all men of the central states and often encroached on and bullied the people.", idiomatic: "----12 Initially, when Emperor Wu destroyed Nanyue, he opened and established Zhuya and Dan'er commanderies on islands in the sea; clerks and soldiers were all men of the central states and often encroached on and bullied the people." },
  { zh: "其民亦暴惡，自以阻絕，數犯吏禁，率數年壹反，殺吏；", literal: "The people too were violent and wicked; trusting themselves cut off by distance, they repeatedly violated official prohibitions—on average once every several years they rebelled and killed officials;", idiomatic: "The people too were violent and wicked; trusting themselves cut off by distance, they repeatedly violated official prohibitions—on average once every several years they rebelled and killed officials;" },
  { zh: "漢輒發兵擊定之。", literal: "Han would then dispatch troops to attack and pacify them.", idiomatic: "Han would then dispatch troops to attack and pacify them." },
  { zh: "二十餘年間，凡六反。", literal: "Within more than twenty years there were six rebellions in all.", idiomatic: "Within more than twenty years there were six rebellions in all." },
  { zh: "至宣帝時，又再反。", literal: "By Emperor Xuan's time they rebelled twice more.", idiomatic: "By Emperor Xuan's time they rebelled twice more." },
  { zh: "上即位之明年，珠崖山南縣反，發兵擊之。", literal: "The year after the emperor took the throne, Shannan county in Zhuya rebelled and troops were dispatched to attack it.", idiomatic: "The year after the emperor took the throne, Shannan county in Zhuya rebelled and troops were dispatched to attack it." },
  { zh: "諸縣更叛，連年不定。", literal: "The various counties rebelled in turn; for successive years it was not settled.", idiomatic: "The various counties rebelled in turn; for successive years it was not settled." },
  { zh: "上博謀於群臣，欲大發軍。", literal: "The emperor broadly deliberated with his ministers and wished to dispatch a great army.", idiomatic: "The emperor broadly deliberated with his ministers and wished to dispatch a great army." },
  { zh: "待詔賈捐之曰：「臣聞堯、舜、禹之聖德，地方不過數千里，西被流沙，東漸於海，朔南暨聲教，言欲與聲教則治之，不欲與者不強治也。", literal: "Awaiting-edict Jia Juanzhi said: \"Your servant has heard that the sage virtue of Yao, Shun, and Yu—their territory did not exceed several thousand li; west it reached the moving sands, east it approached the sea; north and south it extended to their transforming teaching. The saying is: those who wished to receive the transforming teaching were governed; those who did not wish it were not forcibly governed.", idiomatic: "Awaiting-edict Jia Juanzhi said, \"Your servant has heard that the sage virtue of Yao, Shun, and Yu—their territory did not exceed several thousand li; west it reached the moving sands, east it approached the sea; north and south it extended to their transforming teaching. The saying is: those who wished to receive the transforming teaching were governed; those who did not wish it were not forcibly governed." },
  { zh: "故君臣歌德，含氣之物各得其宜。", literal: "Therefore ruler and ministers sang their virtue, and creatures that breathe each obtained their proper place.", idiomatic: "Therefore ruler and ministers sang their virtue, and living creatures each obtained their proper place." },
  { zh: "武丁、成王，殷、周之大仁也，然地東不過江、黃，西不過氐、羌，南不過蠻荊，北不過朔方，是以頌聲並作，視聽之類鹹樂其生，越裳氏重九譯而獻，此非兵革之所能致也。", literal: "Wu Ding and King Cheng were the great benevolence of Yin and Zhou, yet their lands east did not pass the Yangzi and Yellow River, west did not pass the Di and Qiang, south did not pass the southern barbarians and Jing, north did not pass Shuofang—thereby eulogies arose together, and the classes of sight and hearing all rejoiced in their lives; the Yuechang clan, through nine translations, came to offer tribute—this is not what arms and armor could bring about.", idiomatic: "Wu Ding and King Cheng were the great benevolence of Yin and Zhou, yet their lands east did not pass the Yangzi and Yellow River, west did not pass the Di and Qiang, south did not pass the southern barbarians and Jing, north did not pass Shuofang—thereby eulogies arose together, and all who saw and heard rejoiced in their lives; the Yuechang clan, through nine translations, came to offer tribute—this is not what arms and armor could bring about." },
  { zh: "以至於秦，興兵遠攻，貪外虛內而天下潰畔。", literal: "Reaching Qin, it raised armies for distant attacks, coveting the outer while emptying the inner, and all under Heaven split and turned away.", idiomatic: "Reaching Qin, it raised armies for distant attacks, coveting the outer while emptying the inner, and the empire split and turned away." },
  { zh: "孝文皇帝偃武行文，當此之時，斷獄數百，賦役輕簡。", literal: "Emperor Xiao Wen laid down arms and promoted culture; at that time cases judged numbered in the hundreds, and levies and corvée were light and simple.", idiomatic: "Emperor Wen laid down arms and promoted culture; at that time cases judged numbered in the hundreds, and levies and corvée were light and simple." },
  { zh: "孝武皇帝厲兵馬以攘四夷，天下斷獄萬數，賦煩役重，寇賊並起，軍旅數發，父戰死於前，子鬥傷於後，女子乘亭障，孤兒號於道，老母、寡婦飲泣巷哭，是皆廓地泰大，征伐不休之故也。", literal: "Emperor Xiao Wu sharpened troops and horses to repel the four barbarians; cases judged throughout the empire numbered in the tens of thousands, levies were troublesome and corvée heavy, bandits and robbers arose together, armies were repeatedly dispatched—fathers died in battle ahead, sons were wounded fighting behind, women manned the barrier towers, orphans wailed on the roads, old mothers and widows drank tears and wept in the lanes—all because the territory was vast beyond measure and campaigns and attacks did not cease.", idiomatic: "Emperor Wu sharpened troops and horses to repel the four barbarians; cases judged throughout the empire numbered in the tens of thousands, levies were troublesome and corvée heavy, bandits and robbers arose together, armies were repeatedly dispatched—fathers died in battle ahead, sons were wounded fighting behind, women manned the barrier towers, orphans wailed on the roads, old mothers and widows wept in the lanes—all because the territory was vast beyond measure and campaigns did not cease." },
  { zh: "今關東民眾久困，流離道路。", literal: "Now the masses east of the Pass have long been distressed, drifting and scattered on the roads.", idiomatic: "Now the masses east of the Pass have long been distressed, drifting and scattered on the roads." },
  { zh: "人情莫親父母，莫樂夫婦；", literal: "In human feeling none are closer than father and mother, none more joyful than husband and wife;", idiomatic: "In human feeling none are closer than father and mother, none more joyful than husband and wife;" },
  { zh: "至嫁妻賣子，法不能禁，義不能止，此社稷之憂也。", literal: "yet it has reached selling wives and children—law cannot forbid it, righteousness cannot stop it; this is the state's worry.", idiomatic: "yet it has reached selling wives and children—law cannot forbid it, righteousness cannot stop it; this is the state's worry." },
  { zh: "今陛下不忍悁悁之忿，欲驅士眾擠之大海之中，快心幽冥之地，非所以救助饑饉，保全元元也。", literal: "Now Your Majesty cannot bear petty anger and wishes to drive soldiers and masses to crowd them into the midst of the great sea, gratifying your heart in a dark and distant land—this is not the way to rescue famine, or preserve the common people.", idiomatic: "Now Your Majesty cannot bear petty anger and wishes to drive soldiers and masses to crowd them into the midst of the great sea, gratifying your heart in a dark and distant land—this is not the way to rescue famine or preserve the common people." },
  { zh: "詩云：『蠢爾蠻荊，大邦為讎。", literal: "The Odes say: 'Stupid are you, southern barbarians of Jing—the great state becomes your foe.", idiomatic: "The Odes say, 'Stupid are you, southern barbarians of Jing—the great state becomes your foe." },
  { zh: "』言聖人起則後服，中國衰則先畔，自古而患之，何況乃復其南方萬里之蠻乎！", literal: "' The saying is: when sages arise they submit afterward; when the central states decline they rebel first—from antiquity this has been a trouble; how much more to recover the southern ten-thousand-li barbarians!", idiomatic: "' The saying is: when sages arise they submit afterward; when the central states decline they rebel first—from antiquity this has been a trouble; how much more to recover the southern ten-thousand-li barbarians!" },
  { zh: "駱越之人，父子同川而浴，相習以鼻飲，與禽獸無異，本不足郡縣置也。", literal: "The people of Luoyue bathe father and son in the same stream, are accustomed to drinking through the nose, and differ in nothing from birds and beasts—they originally were not worth establishing commanderies and counties over.", idiomatic: "The people of Luoyue bathe father and son in the same stream, are accustomed to drinking through the nose, and differ in nothing from birds and beasts—they originally were not worth establishing commanderies and counties over." },
  { zh: "顓顓獨居一海之中，霧露氣濕，多毒草、蟲蛇、水土之害；", literal: "Dull and alone they dwell in the midst of one sea; fog, dew, and damp qi; many poisonous plants, insects, serpents, and harms of water and soil;", idiomatic: "Dull and alone they dwell in the midst of one sea—fog, dew, and damp air; many poisonous plants, insects, serpents, and harms of water and soil;" },
  { zh: "人未見虜，戰士自死。", literal: "before men have seen the enemy, soldiers die on their own.", idiomatic: "before men have seen the enemy, soldiers die on their own." },
  { zh: "又非獨珠崖有珠、犀、玳瑁也。", literal: "Moreover it is not that Zhuya alone has pearls, rhinoceros horn, and tortoise shell.", idiomatic: "Moreover it is not that Zhuya alone has pearls, rhinoceros horn, and tortoise shell." },
  { zh: "棄之不足惜，不擊不損威。", literal: "To abandon it is not worth regretting; not attacking does not diminish prestige.", idiomatic: "To abandon it is not worth regretting; not attacking does not diminish prestige." },
  { zh: "其民譬猶魚鱉，何足貪也！", literal: "Its people are like fish and turtles—what is there worth coveting!", idiomatic: "Its people are like fish and turtles—what is there worth coveting!" },
  { zh: "臣竊以往者羌軍言之，暴師曾未一年，兵出不逾千里，費四十餘萬萬；", literal: "Your servant privately takes the former Qiang campaign to speak of it: the exposed army had not yet been a year, troops went out not more than a thousand li, and the cost was more than four hundred thousand ten-thousands;", idiomatic: "Your servant privately takes the former Qiang campaign to speak of it: the exposed army had not yet been a year, troops went out not more than a thousand li, and the cost was more than four hundred thousand ten-thousands;" },
  { zh: "大司農錢盡，乃以少府禁錢續之。", literal: "the Grand Minister of Agriculture's money was exhausted, and then the Privy Treasury's sealed money was used to continue it.", idiomatic: "the Grand Minister of Agriculture's money was exhausted, and then the Privy Treasury's sealed money was used to continue it." },
  { zh: "夫一隅為不善，費尚如此，況於勞師遠攻，亡士毋功乎！", literal: "For one corner to be ill-governed the expense was still thus—how much more for tiring the army in distant attack, losing soldiers without achievement!", idiomatic: "For one corner to be ill-governed the expense was still thus—how much more for tiring the army in distant attack, losing soldiers without achievement!" },
  { zh: "求之往古則不合，施之當今又不便，臣愚以為非冠帶之國，《禹貢》所及，《春秋》所治，皆可且無以為。", literal: "Sought in past antiquity it does not fit; applied in the present it is also not convenient. Your servant is foolish and thinks that for states not of cap and sash, what the Yu Tribute reaches, and what the Spring and Autumn governs—all may for the time being be left undone.", idiomatic: "Sought in past antiquity it does not fit; applied in the present it is also not convenient. Your servant thinks that for states not of cap and sash, what the Yu Tribute reaches, and what the Spring and Autumn governs—all may for the time being be left undone." },
  { zh: "願遂棄珠崖，專用恤關東為憂！", literal: "I wish to abandon Zhuya forthwith and devote effort solely to relieving east of the Pass as the worry!", idiomatic: "I wish to abandon Zhuya forthwith and devote effort solely to relieving east of the Pass as the worry!" },
  { zh: "」上以問丞相、御史。", literal: "\" The emperor thereupon questioned the chancellor and censor.", idiomatic: "\" The emperor thereupon questioned the chancellor and censor." },
  { zh: "御史大夫陳萬年以為當擊，丞相-{于定國}-以為：「前日興兵擊之連年，護軍都尉、校尉及丞凡十一人，還者二人，卒士及轉輸死者萬人以上，費用三萬萬餘，尚未能盡降。", literal: "Censor-in-Chief Chen Wannian thought they ought to attack; Chancellor -{于定國}- thought: \"The other day troops were raised to attack them for successive years—Protector of the Army colonels, commandants, and assistants eleven in all; those who returned, two; soldiers and transport dead more than ten thousand; expense more than thirty thousand ten-thousands—and still they could not all be made to submit.", idiomatic: "Censor-in-Chief Chen Wannian thought they ought to attack; Chancellor -{于定國}- thought, \"The other day troops were raised to attack them for successive years—Protector of the Army colonels, commandants, and assistants eleven in all; those who returned, two; soldiers and transport dead more than ten thousand; expense more than thirty thousand ten-thousands—and still they could not all be made to submit." },
  { zh: "今關東困乏，民難搖動，捐之議是，」上從之。", literal: "Now east of the Pass is exhausted and the people are hard to stir—Juanzhi's proposal is right,\" the emperor followed it.", idiomatic: "Now east of the Pass is exhausted and the people are hard to stir—Juanzhi's proposal is right,\" the emperor followed it." },
  { zh: "捐之，賈誼曾孫也。", literal: "Juanzhi was the great-grandson of Jia Yi.", idiomatic: "Juanzhi was the great-grandson of Jia Yi." },
  { zh: "1春，詔曰：「珠崖虜殺吏民，背畔為逆。", literal: "1. Spring: an edict said: \"The barbarians of Zhuya killed officials and people, turned their backs and became rebels.", idiomatic: "1. In spring an edict said, \"The barbarians of Zhuya killed officials and people, turned their backs and became rebels." },
  { zh: "今廷議者或言可擊，或言可守，或欲棄之，其指各殊。", literal: "Now those deliberating at court some say they may be attacked, some say they may be held, some wish to abandon them—their intents each differ.", idiomatic: "Now those deliberating at court some say they may be attacked, some say they may be held, some wish to abandon them—their intents each differ." },
  { zh: "朕日夜惟思議者之言，羞威不行，則欲誅之；", literal: "We day and night only ponder the deliberators' words: if prestige is shamed and not carried out, We wish to execute them;", idiomatic: "We day and night only ponder the deliberators' words: if prestige is shamed and not carried out, We wish to execute them;" },
  { zh: "狐疑辟難，則守屯田；", literal: "if We are doubtful and avoid difficulty, then hold them with garrison farming;", idiomatic: "if We are doubtful and avoid difficulty, then hold them with garrison farming;" },
  { zh: "通乎時變，則憂萬民。", literal: "if We penetrate the changes of the times, then We worry for the myriad people.", idiomatic: "if We penetrate the changes of the times, then We worry for the myriad people." },
  { zh: "夫萬民之飢餓與遠蠻之不討，危孰大焉？", literal: "Of the myriad people's hunger and the distant barbarians' not being punished—which danger is greater?", idiomatic: "Of the myriad people's hunger and the distant barbarians' not being punished—which danger is greater?" },
  { zh: "且宗廟之祭，凶年不備，況乎辟不嫌之辱哉！", literal: "Moreover, for the ancestral temple's sacrifices, in famine years they are not complete—how much more to avoid the disgrace one does not despise!", idiomatic: "Moreover, for the ancestral temple's sacrifices, in famine years they are not complete—how much more to avoid disgrace one does not despise!" },
  { zh: "今關東大困，倉庫空虛，無以相贍，又以動兵，非特勞民，凶年隨之。", literal: "Now east of the Pass is greatly distressed, storehouses empty and void, with nothing to support and relieve them; again to move troops—not only does it weary the people, famine years follow.", idiomatic: "Now east of the Pass is greatly distressed, storehouses empty and void, with nothing to support and relieve them; again to move troops—not only does it weary the people, famine years follow." },
  { zh: "其罷珠崖郡，民有慕義欲內屬，便處之；", literal: "Let Zhuya commandery be abolished; among the people those who admire righteousness and wish to submit inward, conveniently settle them;", idiomatic: "Let Zhuya commandery be abolished; among the people those who admire righteousness and wish to submit inward, conveniently settle them;" },
  { zh: "不欲，勿強。", literal: "those who do not wish it, do not force them.", idiomatic: "those who do not wish it, do not force them." },
  { zh: "」----2夏，四月，乙未晦，茂陵白鶴館災；", literal: "\" ----2 Summer, fourth month, last day yiyi: Maoling's White Crane Lodge burned;", idiomatic: "\" ----2 In summer, the fourth month, on the last day yiyi, Maoling's White Crane Lodge burned;" },
  { zh: "赦天下。", literal: "he pardoned all under Heaven.", idiomatic: "he pardoned all under Heaven." },
  { zh: "----3夏，旱。", literal: "----3 Summer: drought.", idiomatic: "----3 In summer there was drought." },
  { zh: "----4立長沙煬王弟宗為王。", literal: "----4 He established Zong, younger brother of Prince Yang of Changsha, as king.", idiomatic: "----4 He established Zong, younger brother of Prince Yang of Changsha, as king." },
  { zh: "----5長信少府貢禹上言：「諸離宮及長樂宮衛，可減其太半以寬徭役。", literal: "----5 Chief Steward for the Great Dowager's Household Gong Yu submitted words: \"The various detached palaces and the guards of Changle Palace may have more than half reduced to ease corvée.", idiomatic: "----5 Chief Steward for the Great Dowager's Household Gong Yu submitted words, \"The various detached palaces and the guards of Changle Palace may have more than half reduced to ease corvée." },
  { zh: "」六月，詔曰：「朕惟烝庶之饑寒，遠離父母妻子，勞於非業之作，衛於不居之宮，恐非所以佐陰陽之道也。", literal: "\" Sixth month: an edict said: \"We only think of the masses' hunger and cold, far from fathers, mothers, wives, and children, toiling at work not their proper occupation, guarding palaces where We do not dwell—We fear this is not the way to assist the way of yin and yang.", idiomatic: "\" In the sixth month an edict said, \"We only think of the masses' hunger and cold, far from fathers, mothers, wives, and children, toiling at work not their proper occupation, guarding palaces where We do not dwell—We fear this is not the way to assist the way of yin and yang." },
  { zh: "其罷甘泉、建章宮衛，令就農。", literal: "Let the guards of Ganquan and Jianzhang palaces be abolished and ordered to return to farming.", idiomatic: "Let the guards of Ganquan and Jianzhang palaces be abolished and ordered to return to farming." },
  { zh: "百宮各省費。", literal: "The hundred offices should each reduce expenses.", idiomatic: "The hundred offices should each reduce expenses." },
  { zh: "條奏，毋有所諱。", literal: "Memorialize item by item; let nothing be concealed.", idiomatic: "Memorialize item by item; let nothing be concealed." },
  { zh: "」----6是歲，上復擢周堪為光祿勳，堪弟子張猛為光祿大夫、給事中，大見信任。", literal: "\" ----6 That year the emperor again promoted Zhou Kan to Director of the Gentlemen of the Palace; Kan's disciple Zhang Meng to Grand Master of Splendor and Palace Attendant—greatly trusted.", idiomatic: "\" ----6 That year the emperor again promoted Zhou Kan to Director of the Gentlemen of the Palace; Kan's disciple Zhang Meng to Grand Master of Splendor and Palace Attendant—greatly trusted." },
  { zh: "1春，正月，上行幸甘泉，郊泰畤。", literal: "1. Spring, first month: the emperor traveled in favor to Ganquan and sacrificed at the Grand Altar.", idiomatic: "1. In spring, the first month, the emperor traveled to Ganquan and sacrificed at the Grand Altar." },
  { zh: "三月，行幸河東，祠后土；", literal: "Third month: he traveled in favor to Hedong and sacrificed to the Earth Queen;", idiomatic: "In the third month he traveled to Hedong and sacrificed to the Earth Queen;" },
  { zh: "赦汾陰徒。", literal: "he pardoned the convicts of Fenyin.", idiomatic: "he pardoned the convicts of Fenyin." },
  { zh: "1春，正月，以周子南君為周承休侯。", literal: "1. Spring, first month: he made the Lord of Zhouzi South Marquis of Zhou, Heir of Rest.", idiomatic: "1. In spring, the first month, he made the Lord of Zhouzi South Marquis of Zhou, Heir of Rest." },
  { zh: "----2三月，上行幸雍，祠五畤。", literal: "----2 Third month: the emperor traveled in favor to Yong and sacrificed at the Five Altars.", idiomatic: "----2 In the third month the emperor traveled to Yong and sacrificed at the Five Altars." },
  { zh: "----3夏，四月，有星孛於參。", literal: "----3 Summer, fourth month: a comet appeared in Can.", idiomatic: "----3 In summer, the fourth month, a comet appeared in Can." },
  { zh: "----4上用諸儒貢禹等之言，詔太官毋日殺，所具各減半；", literal: "----4 The emperor used the words of the various Confucians Gong Yu and the rest; he decreed the Grand Provisioner not to kill daily, and what was prepared should each be reduced by half;", idiomatic: "----4 The emperor used the words of the various Confucians Gong Yu and the rest; he decreed the Grand Provisioner not to kill daily, and what was prepared should each be reduced by half;" },
  { zh: "乘輿秣馬，無乏正事而已。", literal: "The imperial carriage was to be fed horses—only do not let regular duties be neglected.", idiomatic: "Feed the imperial carriage horses, but only so that regular duties are not neglected." },
  { zh: "罷角抵、上林宮館希御幸者、齊三服官、北假田官、鹽鐵官、常平倉。", literal: "He abolished wrestling contests, Shanglin park lodges rarely favored by imperial visits, the Qi Three-Garment Office, the Beijia field office, the salt-and-iron office, and the Ever-Normal Granary.", idiomatic: "He abolished wrestling contests, Shanglin park lodges rarely visited by the emperor, the Qi Three-Garment Office, the Beijia field office, the salt-and-iron office, and the Ever-Normal Granary." },
  { zh: "博士弟子毋置員，以廣學者。", literal: "Erudite students were not to have a fixed quota, to broaden scholars.", idiomatic: "No fixed quota was set for Erudite students, to broaden the ranks of scholars." },
  { zh: "令民有能通一經者，皆復。", literal: "He ordered that among the people, any who could master one classic were all to receive exemption.", idiomatic: "He ordered that any commoner who could master one classic was to receive full exemption from levies." },
  { zh: "省刑罰七十餘事。", literal: "He reduced punishments in seventy-odd matters.", idiomatic: "He reduced punishments in more than seventy matters." },
  { zh: "----5陳萬年卒。", literal: "----5 Chen Wannian died.", idiomatic: "----5 Chen Wannian died." },
  { zh: "六月，辛酉，長信少府貢禹為御史大夫。", literal: "In the sixth month, on day xinyou, Chief Steward for Eternal Faith Gong Yu became censor-in-chief.", idiomatic: "In the sixth month, on day xinyou, Chief Steward for Eternal Faith Gong Yu became censor-in-chief." },
  { zh: "禹前後言得失書數十上，上嘉其質直，多採用之。", literal: "Yu before and after had submitted dozens of memorials on gains and losses; the emperor praised his plain sincerity and adopted much of it.", idiomatic: "Yu had submitted dozens of memorials on policy gains and losses; the emperor praised his plain sincerity and adopted much of his advice." },
  { zh: "----6匈奴郅支單于自以道遠，又怨漢擁護呼韓邪而不助己，困辱漢使者江乃始等；", literal: "----6 The Xiongnu Chanyu Zhizhi, thinking himself far on the road and resenting that Han supported Huhanye and did not aid himself, distressed and humiliated Han envoys Jiang Naishi and others;", idiomatic: "----6 The Xiongnu chanyu Zhizhi, thinking himself far from Han and resenting Han's support for Huhanye rather than himself, mistreated Han envoys Jiang Naishi and others;" },
  { zh: "遣使奉獻，因求侍子。", literal: "he sent an envoy with tribute and thereby requested the return of his hostage son.", idiomatic: "he sent an envoy with tribute and requested the return of his hostage son." },
  { zh: "漢議遣衛司馬谷吉送之，御史大夫貢禹、博士東海匡衡以為：「郅支單于鄉化末醇，所在絕遠，宜令使者送其子，至塞而還。", literal: "Han deliberated sending Guard Major Gu Ji to escort him; Censor-in-Chief Gong Yu and Erudite Kuang Heng of Donghai held: \"Chanyu Zhizhi's turning toward civilization is not yet ripe; his place is utterly remote—it is fitting to have an envoy escort his son only to the passes and then return.", idiomatic: "Han deliberated sending Guard Major Gu Ji to escort the prince home; Censor-in-Chief Gong Yu and Erudite Kuang Heng of Donghai argued, \"Chanyu Zhizhi's turning toward civilization is not yet secure; his domain is utterly remote—it is fitting to have an envoy escort his son only to the border passes and then return.\"" },
  { zh: "」吉上書言：「中國與夷狄有羈縻不絕之義，今既養全其子十年，德澤甚厚，空絕而不送，近從塞還，示棄捐不畜，使無鄉從之心，棄前恩，立後怨，不便。", literal: "\" Ji submitted a memorial, saying: \"The Central States and the Yi and Di have the meaning of bridling and tying without breaking off; now that his son has been nourished and kept whole for ten years, virtue's favor is very thick—to cut off empty and not send him, having him return only from near the passes, shows casting away and not keeping him, making him have no heart of homeland to follow, abandoning former grace and establishing later resentment—is not expedient.", idiomatic: "\" Ji submitted a memorial, saying, \"The Central States and the barbarians have the principle of keeping them on loose reins without breaking ties; we have now nourished and kept his son whole for ten years, with very great grace—to cut off ties and not send him home, having him return only from near the passes, shows that we cast him away and will not keep him, leaving him no heart to follow his homeland, abandoning former grace and creating later resentment—is inexpedient.\"" },
  { zh: "議者見前江乃無應敵之數，智勇俱困，以致恥辱，即豫為臣憂。", literal: "The debaters, seeing that earlier Jiang had no means to meet the enemy and both wisdom and courage were exhausted, leading to disgrace, thereby forestall worry for your subject.", idiomatic: "The debaters, seeing that Jiang earlier had no means to meet the enemy and that both wisdom and courage were exhausted, leading to disgrace, thereby anticipate worry for your subject." },
  { zh: "臣幸得建強漢之節，承明聖之詔，宣諭厚恩，不宜敢桀。", literal: "Your subject is fortunate to be able to uphold the Han's strong integrity, receive the enlightened sage's edict, proclaim and explain thick grace, and ought not dare to be obstinate.", idiomatic: "Your subject is fortunate to uphold the Han's strong integrity, receive the enlightened emperor's edict, proclaim thick grace, and ought not dare to be obstinate." },
  { zh: "若懷禽獸心，加無道於臣，則單于長嬰大罪，必遁逃遠捨，不敢近邊。", literal: "If he harbors a beast's heart and applies injustice to your subject, then the chanyu will long carry a great crime and is sure to flee far and abandon his seat, not daring to approach the border.", idiomatic: "If he harbors a beast's heart and does violence to your subject, then the chanyu will long bear a great crime and is sure to flee far away, not daring to approach the border." },
  { zh: "沒一使以安百姓，國之計，臣之願也。", literal: "To lose one envoy to secure the hundred surnames is the state's plan and your subject's wish.", idiomatic: "To lose one envoy to secure the common people is the state's plan and your subject's wish." },
  { zh: "願送至庭。", literal: "I wish to escort him to the court.", idiomatic: "I wish to escort him to the chanyu's court." },
  { zh: "」上許焉。", literal: "\" The emperor approved.", idiomatic: "\" The emperor approved." },
  { zh: "既到，郅支單于怒，竟殺吉等；", literal: "When he had arrived, Chanyu Zhizhi was enraged and in the end killed Ji and the others;", idiomatic: "When he arrived, Chanyu Zhizhi was enraged and in the end killed Ji and the others;" },
  { zh: "自知負漢，又聞呼韓邪益強，恐見襲擊，欲遠去。", literal: "knowing himself to have wronged Han, and also hearing that Huhanye grew daily stronger, he feared being attacked and wished to go far away.", idiomatic: "knowing he had wronged Han, and also hearing that Huhanye was growing stronger, he feared attack and wished to go far away." },
  { zh: "會康居王數為烏孫所困，與諸翕侯計，以為：「匈奴大國，烏孫素服屬之。", literal: "It happened that the king of Kangju had repeatedly been distressed by Wusun; with the various xihou he plotted, holding: \"The Xiongnu are a great state; Wusun has long submitted and belonged to them.", idiomatic: "It happened that the king of Kangju had repeatedly been harassed by Wusun; with the various chieftains he plotted, saying, \"The Xiongnu are a great power; Wusun has long submitted to them.\"" },
  { zh: "今郅支單于困厄在外，可迎置東邊，使合兵取烏孫而立之，長無匈奴憂矣。", literal: "Now Chanyu Zhizhi is distressed and stranded abroad; we can welcome and place him on the east, make him combine troops to take Wusun and establish him—then there will long be no Xiongnu worry.", idiomatic: "Now Chanyu Zhizhi is distressed and stranded abroad; we can welcome him and place him in the east, combine forces to take Wusun and establish him there—then we will long be free of Xiongnu trouble.\"" },
  { zh: "」即使使到堅昆，通語郅支。", literal: "\" They thereupon sent an envoy to Jiankun to communicate with Zhizhi.", idiomatic: "\" They thereupon sent an envoy to Jiankun to communicate with Zhizhi." },
  { zh: "郅支素恐，又怨烏孫，聞康居計，大說，遂與相結，引兵而西。", literal: "Zhizhi had long been fearful and again resented Wusun; hearing Kangju's plan, he was greatly pleased, thereupon joined with them, and led his troops west.", idiomatic: "Zhizhi had long been fearful and resented Wusun; hearing Kangju's plan, he was greatly pleased, joined with them, and led his troops west." },
  { zh: "郅支人眾中寒道死，餘財三千人。", literal: "Among Zhizhi's masses many died on the road from cold; only about three thousand remained.", idiomatic: "Many of Zhizhi's followers died on the road from cold; only about three thousand remained." },
  { zh: "到康居，康居王以女妻郅支，郅支亦以女予康居王，康居甚尊敬郅支，欲倚其威以脅諸國。", literal: "When he reached Kangju, the king of Kangju gave his daughter in marriage to Zhizhi; Zhizhi also gave his daughter to the king of Kangju; Kangju greatly honored Zhizhi, wishing to rely on his might to coerce the various states.", idiomatic: "When he reached Kangju, the king of Kangju gave his daughter in marriage to Zhizhi; Zhizhi also gave his daughter to the king of Kangju; Kangju greatly honored Zhizhi, wishing to rely on his might to intimidate the various states." },
  { zh: "郅支數借兵擊烏孫，深入至谷城，殺略民人，驅畜產去。", literal: "Zhizhi repeatedly borrowed troops to attack Wusun, penetrating deep to Valley City, killing and plundering the people, and driving off livestock.", idiomatic: "Zhizhi repeatedly borrowed troops to attack Wusun, penetrating deep to Valley City, killing and plundering the people, and driving off livestock." },
  { zh: "烏孫不敢追。", literal: "Wusun did not dare pursue.", idiomatic: "Wusun did not dare pursue." },
  { zh: "西邊空虛不居者五千里。", literal: "The western border lay empty and uninhabited for five thousand li.", idiomatic: "The western border lay empty and uninhabited for five thousand li." },
  { zh: "----7冬，十二月，丁末，貢禹卒。", literal: "----7 In winter, the twelfth month, on day dingmo, Gong Yu died.", idiomatic: "----7 In winter, the twelfth month, on day dingmo, Gong Yu died." },
  { zh: "丁已，長信少府薛廣德為御史大夫。", literal: "On day dingsi, Chief Steward for Eternal Faith Xue Guangde became censor-in-chief.", idiomatic: "On day dingsi, Chief Steward for Eternal Faith Xue Guangde became censor-in-chief." },
  { zh: "1春，正月，上行幸甘泉，郊泰畤。", literal: "1 In spring, the first month, the emperor traveled in favor to Sweet Springs and sacrificed at the Great Altar.", idiomatic: "1 In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar." },
  { zh: "視畢，因留射獵。", literal: "When the rites were finished, he thereupon remained to shoot and hunt.", idiomatic: "When the rites were finished, he remained to hunt." },
  { zh: "薛廣德上書曰：「竊見關東困極，人民流離。", literal: "Xue Guangde submitted a memorial, saying: \"I have seen that east of the passes is extremely distressed and the people are displaced and adrift.", idiomatic: "Xue Guangde submitted a memorial, saying, \"I have seen that east of the passes is in extreme distress and the people are displaced.\"" },
  { zh: "陛下日撞亡秦之鐘，聽鄭、衛之樂，臣誠悼之。", literal: "Your Majesty daily strikes Qin's bell of ruin and listens to Zheng and Wei's music—your subject is truly grieved.", idiomatic: "Your Majesty daily strikes Qin's bell of ruin and listens to Zheng and Wei music—your subject is truly grieved.\"" },
  { zh: "今士卒暴露，從官勞倦，願陛下亟反宮，思與百姓同憂樂，天下幸甚！", literal: "Now soldiers stand exposed and attending officials are weary with labor; I wish Your Majesty would quickly return to the palace and think to share worry and joy with the hundred surnames—the realm would be greatly fortunate!", idiomatic: "Now soldiers stand exposed and attending officials are weary; I wish Your Majesty would quickly return to the palace and think to share worry and joy with the people—the realm would be greatly fortunate!\"" },
  { zh: "」上即日還。", literal: "\" The emperor returned that same day.", idiomatic: "\" The emperor returned that same day." },
  { zh: "----2二月，詔：「丞相、御史舉質樸、敦厚、遜讓、有行者，光祿歲以此科第郎、從官。", literal: "----2 In the second month, an edict: \"The chancellor and censor are to recommend men who are plain, sincere, humble, yielding, and of conduct; the Director of the Masters of Writing each year is to rank palace gentlemen and attendants by this category.", idiomatic: "----2 In the second month, an edict: \"The chancellor and censor are to recommend men who are plain, sincere, humble, yielding, and of good conduct; the Director of the Masters of Writing each year is to rank palace gentlemen and attendants by this standard.\"" },
  { zh: "」----3三月，赦天下。", literal: "\" ----3 In the third month, he amnestied All-under-Heaven.", idiomatic: "\" ----3 In the third month, he amnestied All-under-Heaven." },
  { zh: "----4雨雪、隕霜，殺桑。", literal: "----4 Rain and snow fell, frost dropped from the sky, and mulberry trees were killed.", idiomatic: "----4 Rain and snow fell, frost dropped from the sky, and mulberry trees were killed." },
  { zh: "----5秋，上酎祭宗廟，出便門，欲御樓船。", literal: "----5 In autumn, the emperor performed the autumnal offering sacrifice at the ancestral temples, went out through Convenience Gate, and wished to ride a tower boat.", idiomatic: "----5 In autumn, the emperor performed the autumnal offering at the ancestral temples, went out through Convenience Gate, and wished to ride a tower boat." },
  { zh: "薛廣德當乘輿車，免冠頓首曰：「宜從橋。", literal: "Xue Guangde was to attend the imperial carriage, removed his cap and knocked his head, saying: \"You ought to go by the bridge.", idiomatic: "Xue Guangde was to attend the imperial carriage, removed his cap and knocked his head, saying, \"You ought to go by the bridge.\"" },
  { zh: "」詔曰：「大夫冠。", literal: "\" An edict said: \"Grandee, put on your cap.", idiomatic: "\" An edict said, \"Grandee, put on your cap.\"" },
  { zh: "」廣德曰：「陛下不聽臣，臣自刎，以血污車輪，陛下不得入廟矣！", literal: "\" Guangde said: \"If Your Majesty will not heed your subject, your subject will cut his own throat and stain the carriage wheels with blood—Your Majesty will not be able to enter the temple!", idiomatic: "\" Guangde said, \"If Your Majesty will not heed your subject, your subject will cut his own throat and stain the carriage wheels with blood—Your Majesty will not be able to enter the temple!\"" },
  { zh: "」上不說。", literal: "\" The emperor was displeased.", idiomatic: "\" The emperor was displeased." },
  { zh: "先驅光祿大夫張猛進曰：「臣聞主聖臣直。", literal: "The vanguard Director of the Masters of Writing Zhang Meng advanced and said: \"Your subject has heard that when the ruler is sage, ministers are upright.", idiomatic: "The vanguard Director of the Masters of Writing Zhang Meng advanced and said, \"Your subject has heard that when the ruler is sage, ministers are upright.\"" },
  { zh: "乘船危，就橋安，聖主不乘危。", literal: "Riding a boat is perilous; taking the bridge is secure—a sage ruler does not ride peril.", idiomatic: "Riding a boat is perilous; taking the bridge is secure—a sage ruler does not court peril.\"" },
  { zh: "御史大夫言可聽。", literal: "The censor-in-chief's words may be heeded.", idiomatic: "The censor-in-chief's words should be heeded.\"" },
  { zh: "」上曰：「曉人不當如是邪！", literal: "\" The emperor said: \"Should not one who understands people be like this!", idiomatic: "\" The emperor said, \"Should not one who understands people be like this!\"" },
  { zh: "」乃從橋。", literal: "\" Thereupon he went by the bridge.", idiomatic: "\" Thereupon he went by the bridge." },
  { zh: "----6九月，隕霜殺稼，天下大饑。", literal: "----6 In the ninth month, frost dropped from the sky and killed the grain crops; All-under-Heaven suffered great famine.", idiomatic: "----6 In the ninth month, frost dropped from the sky and killed the crops; the realm suffered great famine." },
  { zh: "丞相-{于定國}-，大司馬、車騎將軍史高，御史大夫薛廣德，俱以災異乞骸骨。", literal: "Chancellor -{Yu Dingguo}-, Grand Marshal and General of Chariots and Cavalry Shi Gao, and Censor-in-Chief Xue Guangde all requested their bones on account of prodigies and anomalies.", idiomatic: "Chancellor -{Yu Dingguo}-, Grand Marshal and General of Chariots and Cavalry Shi Gao, and Censor-in-Chief Xue Guangde all resigned on account of prodigies and anomalies." },
  { zh: "賜安車、駟馬、黃金六十斤，罷。", literal: "They were granted cushioned carriages, four-horse teams, and sixty jin of gold, and were dismissed.", idiomatic: "They were granted cushioned carriages, four-horse teams, and sixty jin of gold, and were dismissed." },
  { zh: "太子太傅韋玄成為御史大夫。", literal: "Tutor of the Heir Apparent Wei Xuancheng became censor-in-chief.", idiomatic: "Tutor of the Heir Apparent Wei Xuancheng became censor-in-chief." },
  { zh: "廣德歸，縣其安車，以傳示子孫為榮。", literal: "Guangde returned home and displayed his cushioned carriage, transmitting it to show his sons and grandsons as an honor.", idiomatic: "Guangde returned home and displayed his cushioned carriage, passing it down to show his descendants as an honor." },
  { zh: "----7帝之為太子也，從太中大夫孔霸受《尚書》。", literal: "----7 When the emperor was heir apparent, he followed Grand Master of the Palace Kong Ba in receiving the Documents.", idiomatic: "----7 When the emperor was heir apparent, he studied the Documents under Grand Master of the Palace Kong Ba." },
  { zh: "及即位，賜霸爵關內侯，號褒成君，給事中。", literal: "When he took the throne, he granted Ba the rank of marquis within the passes, styled him Lord of Baocheng, and made him attendant within the palace.", idiomatic: "When he took the throne, he granted Ba the rank of marquis within the passes, styled him Lord of Baocheng, and made him attendant within the palace." },
  { zh: "上欲致霸相位，霸為人謙退，不好權勢，常稱「爵位泰過，何德以堪之！", literal: "The emperor wished to elevate Ba to chancellor rank; Ba was by nature humble and retiring, not fond of power and influence, and often said: \"My noble rank is too excessive—what virtue could bear it!", idiomatic: "The emperor wished to elevate Ba to chancellor; Ba was humble and retiring, not fond of power, and often said, \"My noble rank is too high—what virtue could bear it!\"" },
  { zh: "」御史大夫屢缺，上輒欲用霸；", literal: "\" The office of censor-in-chief was repeatedly vacant, and the emperor would then wish to employ Ba;", idiomatic: "\" The office of censor-in-chief was repeatedly vacant, and the emperor would then wish to employ Ba;" },
  { zh: "霸讓位，自陳至於再三。", literal: "Ba yielded the post and stated his reasons again and again.", idiomatic: "Ba yielded the post and stated his reasons repeatedly." },
  { zh: "上深知其至誠，乃弗用。", literal: "The emperor deeply knew his utmost sincerity and therefore did not employ him.", idiomatic: "The emperor deeply knew his utmost sincerity and therefore did not employ him." },
  { zh: "以是敬之，賞賜甚厚。", literal: "Because of this the emperor honored him and bestowed rewards very generously.", idiomatic: "Because of this the emperor honored him and bestowed very generous rewards." },
  { zh: "----8戊子，侍中，衛尉王接為大司馬、車騎將軍。", literal: "----8 On day wuzi, Attendant within the Palace and Commandant of the Guards Wang Jie became grand marshal and general of chariots and cavalry.", idiomatic: "----8 On day wuzi, Attendant within the Palace and Commandant of the Guards Wang Jie became grand marshal and general of chariots and cavalry." },
  { zh: "----9石顯憚周堪、張猛等，數譖毀之。", literal: "----9 Shi Xian feared Zhou Kan, Zhang Meng, and others, and repeatedly slandered and defamed them.", idiomatic: "----9 Shi Xian feared Zhou Kan, Zhang Meng, and others, and repeatedly slandered them." },
  { zh: "劉更生懼其傾危，上書曰：「臣聞舜命九官，濟濟相讓，和之至也。", literal: "Liu Gengsheng feared they would be overturned and submitted a memorial, saying: \"Your subject has heard that when Shun appointed the nine officers, they yielded to one another in abundance—this was harmony at its height.", idiomatic: "Liu Gengsheng feared they would be overthrown and submitted a memorial, saying, \"Your subject has heard that when Shun appointed the nine officers, they yielded to one another in abundance—this was harmony at its height.\"" },
  { zh: "眾臣和於朝則萬物和於野，故簫《韶》九成，鳳皇來儀。", literal: "When the multitude of ministers were harmonious at court, then the myriad things were harmonious in the wilds; therefore when the Xiao Shao was played nine times, the phoenix came to take its place.", idiomatic: "When ministers were harmonious at court, the myriad things were harmonious in the wilds; therefore when the Xiao Shao was played nine times, the phoenix came to take its place.\"" },
  { zh: "至周幽，厲之際，朝廷不和，轉相非怨，則日月薄食，水泉沸騰，山谷易處，霜降失節。", literal: "Down to the time of King You and King Li of Zhou, when the court was not harmonious and ministers turned to blame and resent one another, then sun and moon were eclipsed, springs boiled over, valleys changed their places, and frost fell out of season.", idiomatic: "Down to the time of Kings You and Li of Zhou, when the court was not harmonious and ministers turned to blame and resent one another, sun and moon were eclipsed, springs boiled over, valleys shifted, and frost fell out of season.\"" },
  { zh: "由此觀之，和氣致祥，乖氣致異，祥多者其國安，異眾者其國危。", literal: "Viewed from this, harmonious qi brings auspice, perverse qi brings prodigies; where auspices are many the state is secure, where prodigies are many the state is perilous.", idiomatic: "Viewed from this, harmonious qi brings auspice, perverse qi brings prodigies; where auspices are many the state is secure, where prodigies are many the state is in peril.\"" },
  { zh: "天地之常經，古今之通義也。", literal: "This is Heaven and Earth's constant canon and the common meaning through antiquity and the present.", idiomatic: "This is Heaven and Earth's constant canon and the common meaning through antiquity and the present.\"" },
  { zh: "今陛下開三代之業，招文學之士，優遊寬容，使得並進。", literal: "Now Your Majesty has opened the enterprise of the Three Dynasties, summoned men of letters, and been leisurely, lenient, and tolerant, enabling them to advance together.", idiomatic: "Now Your Majesty has opened the enterprise of the Three Dynasties, summoned men of letters, and been leisurely, lenient, and tolerant, enabling them to advance together.\"" },
  { zh: "今賢不肖渾殽，白黑不分，邪正雜糅，忠讒並進；", literal: "Yet now worthy and unworthy are mixed in confusion, white and black are not distinguished, crooked and straight are intermingled, and loyal and slanderous advance together;", idiomatic: "Yet now worthy and unworthy are mixed in confusion, right and wrong are not distinguished, crooked and straight are intermingled, and loyal and slanderous men advance together;\"" },
  { zh: "章交公車，人滿北軍，朝臣舛午，膠戾乖剌，更相讒訴，轉相是非；", literal: "memorials crowd the imperial carriage office, men fill the Northern Army, court ministers clash at noon, stick fast in perversity and cut against one another, alternately slander and accuse, and turn to judge right and wrong;", idiomatic: "memorials crowd the imperial carriage office, men fill the Northern Army, court ministers clash, stick fast in perversity and cut against one another, alternately slander and accuse, and turn to judge right and wrong;\"" },
  { zh: "所以營惑耳目，感移心意，不可勝載，分曹為黨，往往群朋將同心以陷正臣。", literal: "thereby bewildering ears and eyes, moving and shifting the heart's intent—more than can be recorded; they divide into bureaus and form factions, often banding together to join hearts and entrap upright ministers.", idiomatic: "thereby bewildering ears and eyes and shifting the heart's intent—more than can be recorded; they divide into factions and often band together to entrap upright ministers.\"" },
  { zh: "正臣進者，治之表也；", literal: "When upright ministers advance, it is the outward sign of good governance;", idiomatic: "When upright ministers advance, it is the outward sign of good governance;\"" },
  { zh: "正臣陷者，亂之機也；", literal: "when upright ministers are entrapped, it is the mechanism of disorder;", idiomatic: "when upright ministers are entrapped, it is the mechanism of disorder;\"" },
  { zh: "乘治亂之機，未知孰任，而災異數見，此臣所以寒心者也。", literal: "seizing the mechanism between order and disorder, not knowing who will bear responsibility, while prodigies and anomalies repeatedly appear—this is why your subject's heart is chilled.", idiomatic: "seizing the mechanism between order and disorder, not knowing who will bear responsibility, while prodigies and anomalies repeatedly appear—this is why your subject's heart is chilled.\"" },
  { zh: "初元以來六年矣，按春秋六年之中，災異未有稠如今者也。", literal: "Six years have passed since the beginning of Chuyuan; examining the Spring and Autumn Annals' six-year spans, prodigies and anomalies have never been as dense as now.", idiomatic: "Six years have passed since the beginning of Chuyuan; examining six-year spans in the Spring and Autumn Annals, prodigies and anomalies have never been as dense as now.\"" },
  { zh: "原其所以然者，由讒邪並進也；", literal: "Tracing why it is so, it is because slander and wickedness advance together;", idiomatic: "Tracing why it is so, it is because slander and wickedness advance together;\"" },
  { zh: "讒邪之所以並進者，由上多疑心，既已用賢人而行善政，如或譖之，則賢人退而善政還矣。", literal: "the reason slander and wickedness advance together is that above there is much doubting heart; having already employed worthy men and practiced good government, if someone slanders them, then worthy men withdraw and good government returns.", idiomatic: "the reason slander and wickedness advance together is that above there is much doubting; having already employed worthy men and practiced good government, if someone slanders them, worthy men withdraw and good government is undone.\"" },
  { zh: "夫執狐疑之心者，來讒賊之口；", literal: "One who holds a fox-doubting heart invites the mouths of slanderous villains;", idiomatic: "One who holds a doubting heart invites slanderous mouths;\"" },
  { zh: "持不斷之意者，開群枉之門；", literal: "one who maintains an undecisive intent opens the gate for a crowd of crooked men;", idiomatic: "one who maintains an undecisive intent opens the gate for a crowd of crooked men;\"" },
  { zh: "讒邪進則眾賢退，群枉盛則正士消。", literal: "when slander and wickedness advance, the multitude of worthies withdraw; when the crowd of crooked men flourishes, upright gentlemen vanish.", idiomatic: "when slander and wickedness advance, the multitude of worthies withdraw; when crooked men flourish, upright gentlemen vanish.\"" },
  { zh: "故《易》有《否》、《泰》，小人道長，君子道消，則政日亂；", literal: "Therefore the Changes has Pi and Tai: when the petty man's Way grows long and the gentleman's Way wanes, government daily grows disordered;", idiomatic: "Therefore the Changes has Pi and Tai: when the petty man's way grows long and the gentleman's way wanes, government daily grows disordered;\"" },
  { zh: "君子道長，小人道消，則政日治。", literal: "when the gentleman's Way grows long and the petty man's Way wanes, government daily grows well ordered.", idiomatic: "when the gentleman's way grows long and the petty man's way wanes, government daily grows well ordered.\"" },
  { zh: "昔者鯀、共工、驩兜與舜、禹雜處堯朝，周公與管、蔡並居周位，當是時，迭進相毀，流言相謗，豈可勝道哉！", literal: "In antiquity Gun, Gong Gong, and Huan Dou were mixed in Yao's court with Shun and Yu; the Duke of Zhou and Guan and Cai together held Zhou offices—at that time they advanced in turn to destroy one another and floating words slandered one another—how could it all be told!", idiomatic: "In antiquity Gun, Gong Gong, and Huan Dou were mixed in Yao's court with Shun and Yu; the Duke of Zhou and Guan and Cai together held Zhou offices—at that time they advanced in turn to destroy one another and rumors slandered one another—how could it all be told!\"" },
  { zh: "帝堯、成王能賢舜、禹、周公而消共工、管、蔡，故以大治，榮華至今。", literal: "Emperors Yao and King Cheng were able to treat Shun, Yu, and the Duke of Zhou as worthy and eliminate Gong Gong, Guan, and Cai; therefore there was great order and glory and splendor down to the present.", idiomatic: "Emperors Yao and King Cheng were able to treat Shun, Yu, and the Duke of Zhou as worthy and eliminate Gong Gong, Guan, and Cai; therefore there was great order and glory down to the present.\"" },
  { zh: "孔子與季、孟偕仕於魯，李斯與叔孫俱宦於秦，定公、始皇賢季、孟、李斯而消孔子、叔孫，故以大亂，污辱至今。", literal: "Confucius served in Lu together with the Ji and Meng clans; Li Si and Shusun both held office in Qin; Duke Ding and the First Emperor treated the Ji, Meng, and Li Si as worthy and eliminated Confucius and Shusun—therefore there was great disorder and filth and disgrace down to the present.", idiomatic: "Confucius served in Lu together with the Ji and Meng clans; Li Si and Shusun both held office in Qin; Duke Ding and the First Emperor treated the Ji, Meng, and Li Si as worthy and eliminated Confucius and Shusun—therefore there was great disorder and disgrace down to the present.\"" },
  { zh: "故治亂榮辱之端，在所信任；", literal: "Therefore the beginning of order and disorder, glory and disgrace, lies in whom one trusts;", idiomatic: "Therefore the beginning of order and disorder, glory and disgrace, lies in whom one trusts;\"" },
  { zh: "信任既賢，在於堅固而不移。", literal: "once trust is placed in the worthy, it lies in being firm and not shifting.", idiomatic: "once trust is placed in the worthy, it lies in being firm and not shifting.\"" },
  { zh: "《詩》云：『我心匪石，不可轉也，言守善篤也。", literal: "The Odes says: 'My heart is not stone—it cannot be turned,' speaking of steadfastly keeping to the good.", idiomatic: "The Odes says, \"My heart is not stone—it cannot be turned,\" speaking of steadfastly keeping to the good.\"" },
  { zh: "《易》曰：『渙汗其大號』，言號令如汗，汗出而不反者也。", literal: "The Changes says: 'He disperses sweat with his great proclamation,' meaning that orders are like sweat—once sweat issues forth it does not return.", idiomatic: "The Changes says, \"He disperses sweat with his great proclamation,\" meaning that orders are like sweat—once sweat issues forth it does not return.\"" },
  { zh: "今出善令未能逾時而反，是反汗也；", literal: "Now good orders are issued but cannot pass the season before being reversed—this is reversing sweat;", idiomatic: "Now good orders are issued but cannot pass the season before being reversed—this is reversing sweat;\"" },
  { zh: "用賢未能三旬而退，是轉石也。", literal: "employing the worthy but not reaching thirty days before dismissing them—this is turning stone.", idiomatic: "employing the worthy but not reaching thirty days before dismissing them—this is turning stone.\"" },
  { zh: "《論語》曰：『見不善如探湯。", literal: "The Analects says: 'Seeing what is not good is like probing boiling water.'", idiomatic: "The Analects says, \"Seeing what is not good is like probing boiling water.\"" },
  { zh: "』今二府奏佞謅不當在位，歷年而不去。", literal: "' Now the Two Offices memorialize that flatterers and sycophants ought not to hold office, yet year after year they are not removed.", idiomatic: "\" Now the Two Offices memorialize that flatterers and sycophants ought not to hold office, yet year after year they are not removed.\"" },
  { zh: "故出令則如反汗，用賢則如轉石，去佞則如撥山，如此，望陰陽之調，不亦難乎！", literal: "Therefore issuing orders is like reversing sweat, employing the worthy is like turning stone, removing flatterers is like moving mountains—with this, to hope for the harmony of yin and yang—is it not difficult!", idiomatic: "Therefore issuing orders is like reversing sweat, employing the worthy is like turning stone, removing flatterers is like moving mountains—with this, to hope for the harmony of yin and yang—is it not difficult!\"" },
  { zh: "是以群小窺見間隙，緣飾文字，巧言醜詆，流言、飛文嘩於民間。", literal: "Because of this the crowd of petty men spy out gaps, trim and adorn their words, use clever speech to defame uglily, and floating words and flying writings clamor among the people.", idiomatic: "Because of this petty men spy out gaps, trim and adorn their words, use clever speech to defame, and rumors and flying writings clamor among the people.\"" },
  { zh: "故《詩》云：『憂心悄悄，慍於群小，』小人成群，誠足慍也。", literal: "Therefore the Odes says: 'My worried heart is secret, angry at the crowd of petty men'—when petty men form crowds, it is truly enough to anger one.", idiomatic: "Therefore the Odes says, \"My worried heart is secret, angry at the crowd of petty men\"—when petty men form crowds, it is truly enough to anger one.\"" },
  { zh: "昔孔子與顏淵、子貢更相稱譽，不為朋黨；", literal: "In antiquity Confucius with Yan Yuan and Zigong praised one another in turn and did not form factions;", idiomatic: "In antiquity Confucius with Yan Yuan and Zigong praised one another in turn and did not form factions;\"" },
  { zh: "禹、稷與皋陶傳相汲引，不為比周，何則？", literal: "Yu and Ji with Gao Yao passed on and drew one another up and did not form cliquish alliances—why was it so?", idiomatic: "Yu and Ji with Gao Yao passed on and drew one another up and did not form cliquish alliances—why was it so?" },
  { zh: "忠於為國，無邪心也。", literal: "Loyal in serving the state, without a wicked heart.", idiomatic: "They were loyal in serving the state, without wicked intent." },
  { zh: "今佞邪與賢臣並交戟之內，合黨共謀，違善依惡，歙歙訿訿，數設危險之言，欲以傾移主上，如忽然用之，此天地之所以先戒，災異之所以重至者也。", literal: "Now the sycophantic and wicked and worthy ministers together within crossed halberds, join factions and plot together, turn from good and rely on evil, whisper and clamor, repeatedly set forth dangerous words, wishing thereby to overturn and shift the sovereign—if suddenly employed, this is why Heaven and Earth give prior warnings and why calamities and anomalies repeatedly arrive.", idiomatic: "Now the sycophantic and wicked mingle with worthy ministers in the same court, form factions and plot together, turn from good and rely on evil, whisper and clamor, and repeatedly utter dangerous words, wishing to sway the sovereign. If such men were suddenly put in power, that is why Heaven and Earth give warnings beforehand and why calamities and portents come again and again." },
  { zh: "自古明聖未有無誅而治者也，故舜有四放之罰，孔子有兩觀之誅，然後聖化可得而行也。", literal: "From antiquity enlightened sages have never governed without executions; therefore Shun had the punishment of four banishments, Confucius had the execution at the two watchtowers—only then could sage transformation be carried out.", idiomatic: "Since antiquity no enlightened sage has ever governed without punishments. Shun had the four banishments, and Confucius had the execution at the two watchtowers—only then could sage transformation be carried out." },
  { zh: "今以陛下明知，誠深思天地之心，覽《否》、《泰》之卦，歷周、唐之所進以為法，原秦、魯之所消以為戒，考祥應之福、災異之禍，以揆當世之變，放遠佞邪之黨，壞散險詖之聚，杜閉群枉之門，廣開眾正之路，決斷狐疑，分別猶豫，便是非炳然可知，則百異消滅而眾祥並至，太平之基，萬世之利也。", literal: "Now with Your Majesty's clear understanding, truly deeply ponder Heaven and Earth's heart, review the hexagrams Pi and Tai, pass through what Zhou and Tang advanced and take it as model, trace what Qin and Lu consumed away and take it as warning, examine the blessings of auspicious responses and the disasters of calamities and anomalies to measure the changes of the present age, release and send far the faction of sycophants and the wicked, break up and scatter gatherings of dangerous slander, shut and close the gates of many perversities, broadly open the road of the multitude of the upright, decisively cut off doubt, distinguish hesitation—then right and wrong will be brilliantly clear and knowable; then the hundred anomalies will vanish and the many auspicious signs will arrive together—the foundation of great peace, the benefit of ten thousand generations.", idiomatic: "Now, with Your Majesty's clear understanding, truly ponder Heaven and Earth's intent, study the hexagrams Pi and Tai, take what Zhou and Tang advanced as your model and what Qin and Lu destroyed themselves by as your warning, weigh the blessings of auspicious omens against the disasters of portents to gauge the changes of the age, banish the faction of sycophants and the wicked, break up gatherings of dangerous slander, shut the gates of perversity, and open wide the path of the upright. Cut through doubt and distinguish what is uncertain, so that right and wrong stand clear; then the hundred anomalies will vanish, many auspicious signs will come together, and the foundation of great peace and the benefit of ten thousand generations will be secured." },
  { zh: "」顯見其書，愈與許、史比而怨更生等。", literal: "\" Xian saw his memorial and all the more aligned with Xu and Shi while resenting Gengsheng and the others.", idiomatic: "\" When Xian saw the memorial, he drew still closer to Xu and Shi and bore resentment toward Gengsheng and his associates." },
  { zh: "是歲，夏寒，日青無光，顯及許、史皆言堪、猛用事之咎。", literal: "That year, summer was cold; the sun was greenish and without light; Xian and Xu and Shi all said it was the fault of Kan and Meng holding power.", idiomatic: "That year summer was cold, the sun looked greenish and dim, and Xian together with Xu and Shi all said it was because Kan and Meng were wielding power." },
  { zh: "上內重堪，又患眾口之浸潤，無所取信。", literal: "The emperor inwardly valued Kan highly, yet also worried at the soaking infiltration of many mouths, with nothing by which to take faith.", idiomatic: "The emperor inwardly valued Kan highly, yet also worried that constant slander from many quarters left him nothing he could trust." },
  { zh: "時長安令楊興以材能幸，常稱譽堪，上欲以為助，乃見問興：「朝臣斷斷不可光祿勳，何邪？", literal: "At the time Metropolitan Magistrate Yang Xing, favored for talent and ability, often praised Kan; the emperor wished to use him as help and therefore summoned and asked Xing: \"The court ministers insistently say the Grand Master of Splendor cannot serve—why?", idiomatic: "At the time Metropolitan Magistrate Yang Xing, favored for his talent, often praised Kan. The emperor wished to use him as an ally and therefore summoned Xing and asked, \"The court ministers keep insisting that the Grand Master of Splendor cannot serve—why is that?" },
  { zh: "」興者，傾巧士，謂上疑堪，因順指曰：「堪非獨不可於朝廷，自-{州里}-亦不可也！", literal: "\" Xing was a crafty, leaning sort of man; thinking the emperor doubted Kan, he therefore followed the thrust and said: \"Kan is not only unfit at court—even in his own -{州里}- he is unfit!", idiomatic: "\" Xing was a crafty opportunist. Seeing that the emperor doubted Kan, he followed the emperor's inclination and said, \"Kan is not only unfit at court—even in his own -{州里}- he is unfit!\"" },
  { zh: "臣見眾人聞堪與劉更生等謀毀骨肉，以為當誅；", literal: "Your subject has seen that when the multitude heard Kan and Liu Gengsheng and others plotted to destroy flesh-and-bone kin, they thought he ought to be executed;", idiomatic: "Your subject has seen that when people heard Kan and Liu Gengsheng and others were plotting to harm the emperor's own kin, they thought he ought to be executed;" },
  { zh: "故臣前書言堪不可誅傷，為國養恩也。", literal: "therefore your subject in a former memorial said Kan ought not be executed or harmed—it was to nurture grace for the state.", idiomatic: "therefore your subject wrote earlier that Kan ought not be executed or harmed, in order to preserve grace for the state." },
  { zh: "」上曰：「然此何罪而誅？", literal: "\" The emperor said: \"Yet what crime is this for execution?", idiomatic: "\" The emperor said, \"Yet what crime would justify execution?" },
  { zh: "今宜奈何？", literal: "What ought be done now?", idiomatic: "What should be done now?" },
  { zh: "」興曰：「臣愚以為可賜爵關內侯，食邑三百戶，勿令典事。", literal: "\" Xing said: \"Your subject foolishly thinks he may be granted rank as Marquis within the Passes, with a fief of three hundred households, and not be allowed to handle affairs.", idiomatic: "\" Xing said, \"Your subject foolishly thinks he might be granted rank as Marquis within the Passes, with a fief of three hundred households, and not be allowed to handle affairs." },
  { zh: "明主不失師傅之恩，此最策之得者也。", literal: "An enlightened ruler does not lose the grace owed a teacher—this is the most successful policy.", idiomatic: "An enlightened ruler does not cast off the grace owed a teacher—this is the best possible policy." },
  { zh: "」上於是疑之。", literal: "\" The emperor thereupon came to doubt him.", idiomatic: "\" The emperor thereupon came to doubt Kan." },
  { zh: "司隸校尉琅邪諸葛豐始以特立剛直著名於朝，數侵犯貴戚，在位多言其短。", literal: "Director of Convict Labor Zhuge Feng of Langye was at first famed in court for standing alone and being sternly upright; he repeatedly encroached on noble kin, and those in office often spoke of his faults.", idiomatic: "Director of Convict Labor Zhuge Feng of Langye was at first famed at court for his uncompromising integrity; he repeatedly clashed with powerful families, and those in office often spoke of his faults." },
  { zh: "後坐春夏系治人，徙城門校尉。", literal: "Later he was convicted for imprisoning and prosecuting people in spring and summer and was transferred to be Commandant of the City Gates.", idiomatic: "Later he was convicted for imprisoning and prosecuting people in spring and summer and was transferred to Commandant of the City Gates." },
  { zh: "豐於是上書告堪、猛罪，上不直豐，乃制詔御史：「城門校尉豐，前與光祿勳、光祿大夫猛在朝之時，數稱言堪、猛之美。", literal: "Feng thereupon submitted a memorial accusing Kan and Meng of crimes; the emperor did not side with Feng and therefore issued an edict to the imperial censor: \"Commandant of the City Gates Feng, when formerly together with the Grand Master of Splendor and Grand Master of the Palace Meng at court, repeatedly spoke of Kan and Meng's excellence.", idiomatic: "Feng thereupon submitted a memorial accusing Kan and Meng of crimes. The emperor did not side with Feng and issued an edict to the imperial censor: \"Commandant of the City Gates Feng, when he was at court with the Grand Master of Splendor and Grand Master of the Palace Meng, repeatedly praised Kan and Meng." },
  { zh: "豐前為司隸校尉，不順四時，修法度，專作苛暴以獲虛威；", literal: "Feng formerly as Director of Convict Labor did not follow the four seasons, revised laws and standards, and exclusively made harsh cruelty to obtain empty prestige;", idiomatic: "When Feng was Director of Convict Labor he ignored the seasons, revised laws and standards, and relied on harsh cruelty to win empty prestige;" },
  { zh: "朕不忍下吏，以為城門校尉。", literal: "We could not bear to send him down to the officials and made him Commandant of the City Gates.", idiomatic: "We could not bear to hand him over to the law officers and made him Commandant of the City Gates instead." },
  { zh: "不內省諸己，而反怨堪、猛以求報舉，告按無證之辭，暴揚難驗之罪，毀譽恣意，不顧前言，不信之大也。", literal: "He does not inwardly examine himself, yet on the contrary resents Kan and Meng to seek retaliation and impeachment, reporting and prosecuting words without evidence, openly displaying crimes hard to verify, praise and blame as he pleases, not looking to his former words—great untrustworthiness.", idiomatic: "He does not examine himself, yet resents Kan and Meng and seeks retaliation, lodging accusations without evidence and publicly airing charges hard to prove, praising and blaming as he pleases without regard to his former words—this is gross faithlessness." },
  { zh: "朕憐豐之耆老，不忍加刑，其免為庶人！", literal: "We pity Feng's old age and cannot bear to add punishment; let him be dismissed as a commoner!", idiomatic: "We pity Feng in his old age and cannot bear to punish him further; let him be dismissed as a commoner!\"" },
  { zh: "」又曰：「豐言堪、猛貞信不立，朕閔而不治，又惜其材能未有所效，其左遷堪為河東太守，猛槐里令。", literal: "\" He also said: \"Feng said Kan and Meng's uprightness and trustworthiness were not established; We pitied them and did not prosecute, yet also cherished that their talent and ability had not yet shown effect—let Kan be demoted to Administrator of Hedong, and Meng Magistrate of Huaili.", idiomatic: "\" He also said, \"Feng claimed Kan and Meng lacked integrity; We pitied them and did not prosecute, yet also regretted that their talents had not yet borne fruit—demote Kan to Administrator of Hedong and Meng to Magistrate of Huaili.\"" },
  { zh: ":臣光曰：諸葛豐之於堪、猛，前譽而後毀，其志非為朝廷進善而去奸也，欲比周求進而已矣。", literal: ": Minister Guang said: Zhuge Feng toward Kan and Meng—first praising, afterward destroying—the intent was not to advance good for the court and remove wickedness; he wished only to form cliques and seek advancement.", idiomatic: ": Minister Guang said: Zhuge Feng toward Kan and Meng praised them first and slandered them afterward. His aim was not to advance good for the court and remove the wicked, but only to form factions and seek promotion." },
  { zh: "斯亦鄭朋、楊興之流，烏在其為剛直哉！", literal: "He too is of the sort of Zheng Peng and Yang Xing—wherein lies his being stern and upright!", idiomatic: "He belongs to the same breed as Zheng Peng and Yang Xing—where is the integrity in that!" },
  { zh: "人君者，察美惡，辨是非，賞以勸善，罰以懲奸，所以為治也。", literal: "The ruler of men examines beauty and ugliness, distinguishes right and wrong, rewards to encourage good, punishes to chastise wickedness—this is how he governs.", idiomatic: "A ruler examines good and evil, distinguishes right from wrong, rewards to encourage good conduct, and punishes to chastise wickedness—that is how he governs." },
  { zh: "使豐言得實，則豐不當絀；", literal: "If Feng's words were substantiated, then Feng ought not have been demoted;", idiomatic: "If Feng's charges were true, then Feng ought not have been demoted;" },
  { zh: "若其誣罔，則堪、猛何辜焉！", literal: "if they were false and deceptive, then what crime had Kan and Meng!", idiomatic: "if they were false, then what crime had Kan and Meng committed!" },
  { zh: "今兩責而俱棄之，則美惡、是非果安在哉！", literal: "Now both are blamed and both are cast aside—then where in truth are beauty and ugliness, right and wrong!", idiomatic: "Now both parties are blamed and both are cast aside—then where do good and evil, right and wrong, actually lie!" },
  { zh: "----10賈捐之與楊興善。", literal: "----10 Jia Juanzhi was on good terms with Yang Xing.", idiomatic: "----10 Jia Juanzhi was on good terms with Yang Xing." },
  { zh: "捐之數短石顯，以故不得官，稀復進見；", literal: "Juanzhi repeatedly spoke ill of Shi Xian and for this reason did not obtain office, rarely gaining audience again;", idiomatic: "Juanzhi repeatedly criticized Shi Xian and for that reason could not obtain office and rarely gained audience again;" },
  { zh: "興新以材能得幸。", literal: "Xing had newly been favored for talent and ability.", idiomatic: "Xing had newly been favored for his talent." },
  { zh: "捐之謂興曰：「京兆尹缺，使我得見，言君蘭，京兆尹可立得。", literal: "Juanzhi said to Xing: \"The Metropolitan Governorship is vacant; if you let me gain audience and speak for you, Lord Lan, the Metropolitan Governorship can be obtained at once.", idiomatic: "Juanzhi said to Xing, \"The metropolitan governorship is vacant. If you let me gain audience and speak for you, Lord Lan, you can obtain the metropolitan governorship at once.\"" },
  { zh: "」興曰：「君房下筆，言語妙天下；", literal: "\" Xing said: \"Lord Fang, when you put pen to paper, your words are the wonder of All-under-Heaven;", idiomatic: "\" Xing said, \"Lord Fang, when you take up the brush your words are unmatched under Heaven;" },
  { zh: "使君房為尚書令，勝五鹿充宗遠甚。", literal: "if Lord Fang were made Director of the Masters of Writing, he would far surpass Wulu Chongzong.", idiomatic: "if you were made Director of the Masters of Writing, you would far surpass Wulu Chongzong." },
  { zh: "」捐之曰：「令我得代充宗，君蘭為京兆，京兆，郡國首，尚書，百官本，天下真大治，士則不隔矣！", literal: "\" Juanzhi said: \"Let me replace Chongzong, and Lord Lan be Metropolitan Governor—Chang'an is the head of commanderies and kingdoms, the Masters of Writing are the root of the hundred officials; All-under-Heaven would truly be greatly governed, and scholars would not be blocked!", idiomatic: "\" Juanzhi said, \"Let me replace Chongzong and you, Lord Lan, become metropolitan governor. Chang'an is the head of the commanderies and kingdoms, and the Masters of Writing are the root of the hundred officials. Then the empire would truly be well governed and scholars would no longer be shut out!\"" },
  { zh: "」捐之復短石顯，興曰：「顯方貴，上信用之；", literal: "\" Juanzhi again spoke ill of Shi Xian; Xing said: \"Xian is just now honored and the emperor trusts and employs him;", idiomatic: "\" Juanzhi again criticized Shi Xian. Xing said, \"Xian is at the height of power and the emperor trusts him;" },
  { zh: "今欲進，第從我計，且與合意，即得入矣！", literal: "if you now wish to advance, simply follow my plan—for the moment agree with his intent, and you can enter at once!", idiomatic: "if you wish to advance now, simply follow my plan—for the moment agree with him, and you can get in at once!\"" },
  { zh: "」捐之即與興共為薦顯奏，稱譽其美，以為宜賜爵關內侯，引其兄弟以為諸曹；", literal: "\" Juanzhi then together with Xing jointly drafted a memorial recommending Xian, praising his excellence, holding that he ought to be granted rank as Marquis within the Passes, and bringing in his brothers to serve in the various bureaus;", idiomatic: "\" Juanzhi then joined Xing in drafting a memorial recommending Xian, praising his merits, proposing that he be granted rank as Marquis within the Passes, and bringing in his brothers to serve in the various bureaus;" },
  { zh: "又共為薦興奏，以為可試守京兆尹。", literal: "they also jointly drafted a memorial recommending Xing, holding that he could be tried as acting Metropolitan Governor.", idiomatic: "they also jointly drafted a memorial recommending Xing, proposing that he be tried as acting metropolitan governor." },
  { zh: "石顯聞知，白之上，乃下興、捐之獄，令顯治之，奏「興，捐之懷詐偽，更相薦譽，欲得大位，罔上不道！", literal: "Shi Xian heard and knew, reported to the emperor, and thereupon sent Xing and Juanzhi down to prison, ordering Xian to prosecute them; he memorialized: \"Xing and Juanzhi harbored deceit and falsity, mutually recommending and praising each other, wishing to obtain high position—deceiving the sovereign, undao!", idiomatic: "When Shi Xian learned of this, he reported it to the emperor. Xing and Juanzhi were sent to prison and Xian was ordered to prosecute them. He memorialized, \"Xing and Juanzhi harbored deceit, praised each other in turn, and sought high office—deceiving the sovereign, a capital offense!\"" },
  { zh: "」捐之竟坐棄市，興髡鉗為城旦。", literal: "\" Juanzhi in the end was convicted and executed in the marketplace; Xing was shaved, fettered, and made a corvée laborer.", idiomatic: "\" Juanzhi was in the end executed in the marketplace; Xing was shaved, fettered, and sentenced to corvée labor as a wall-builder." },
  { zh: ":臣光曰：君子以正攻邪，猶懼不克。", literal: ": Minister Guang said: The gentleman uses the upright to attack the wicked, yet still fears he may not overcome.", idiomatic: ": Minister Guang said: A gentleman uses rectitude to attack wickedness, yet still fears he may not prevail." },
  { zh: "況捐之以邪攻邪，其能免乎！", literal: "How much more when Juanzhi used wickedness to attack wickedness—how could he escape!", idiomatic: "How much less can one who uses wickedness to attack wickedness, as Juanzhi did, hope to escape!" },
  { zh: "----11徙清河王竟為中山王。", literal: "----11 King Jing of Qinghe was moved to become King of Zhongshan.", idiomatic: "----11 King Jing of Qinghe was moved to become King of Zhongshan." },
  { zh: "----12匈奴呼韓邪單于民眾益盛，塞下禽獸盡，單于足以自衛，不畏郅支，其大臣多勸單于北歸者。", literal: "----12 Among the Xiongnu, Chanyu Huhanye's masses grew ever more prosperous; beasts below the frontier passes were exhausted; the chanyu was sufficient to defend himself and did not fear Zhizhi; many of his great ministers urged the chanyu to return north.", idiomatic: "----12 Among the Xiongnu, Chanyu Huhanye's following grew ever stronger; game below the frontier passes was exhausted; the chanyu had enough strength to defend himself and no longer feared Zhizhi; and many of his great ministers urged him to return north." },
  { zh: "久之，單于竟北歸庭，民眾稍稍歸之，其國遂定。", literal: "After a long time, the chanyu at last returned north to his court; the masses gradually returned to him, and his state was thereby settled.", idiomatic: "After a long time the chanyu at last returned north to his court; his people gradually came back to him, and his state was thereby settled." },
  { zh: "1春，二月，赦天下。", literal: "1 Spring, second month, amnesty for All-under-Heaven.", idiomatic: "1 In spring, the second month, an amnesty was proclaimed for the empire." },
  { zh: "----2丁酉，御史大夫韋玄成為丞相；", literal: "----2 On dingyou, Censor-in-Chief Wei Xuancheng became chancellor;", idiomatic: "----2 On dingyou, Censor-in-Chief Wei Xuancheng became chancellor;" },
  { zh: "右扶風鄭弘為御史大夫。", literal: "Zheng Hong of Right Fufeng became censor-in-chief.", idiomatic: "Zheng Hong of Right Fufeng became censor-in-chief." },
  { zh: "----3三月，壬戌朔，日有食之。", literal: "----3 Third month, on the first day renxu, there was a solar eclipse.", idiomatic: "----3 In the third month, on the first day renxu, there was a solar eclipse." },
  { zh: "----4夏，六月，赦天下。", literal: "----4 Summer, sixth month, amnesty for All-under-Heaven.", idiomatic: "----4 In summer, the sixth month, an amnesty was proclaimed for the empire." },
  { zh: "----5上問給事中匡衡以地震日食之變，衡上疏曰：「陛下躬聖德，開太平之路，閔愚吏民觸法抵禁，比年大赦，使百姓得改行自新，天下幸甚！", literal: "----5 The emperor questioned Palace Attendant Kuang Heng on the changes of earthquake and solar eclipse; Heng submitted a memorial saying: \"Your Majesty personally embodies sage virtue, opens the road of great peace, pities foolish officials and people who touch the law and reach prohibition; in successive years great amnesties have let the common people reform conduct and renew themselves—All-under-Heaven is greatly fortunate!", idiomatic: "----5 The emperor questioned Palace Attendant Kuang Heng about the earthquake and solar eclipse. Heng submitted a memorial saying, \"Your Majesty personally embodies sage virtue and opens the road to great peace. You pity foolish officials and common people who stumble into the law. Year after year you have proclaimed great amnesties so the people may reform and renew themselves—the empire is greatly fortunate!\"" },
  { zh: "臣竊見大赦之後，奸邪不為衰止，今日大赦，明日犯法，相隨入獄，此殆導之未得其務也。", literal: "Your subject has privately seen that after great amnesties the wicked do not decline and stop; today a great amnesty, tomorrow violating the law—they follow one another into prison; this is probably that guidance has not obtained its proper task.", idiomatic: "Your subject has observed that after great amnesties wicked conduct does not decline. Today there is a great amnesty, tomorrow people break the law again and enter prison in succession—this probably means guidance has not hit its mark." },
  { zh: "今天下俗，貪財賤義，好聲色，上侈靡，親戚之恩薄，婚姻之黨隆，苟合徼幸，以身設利；", literal: "Now the customs of All-under-Heaven: they value wealth and slight righteousness, delight in sound and color, exalt extravagance and excess, kinship grace is thin, marriage factions are exalted, they hastily join and seek fortune, setting up profit with their persons;", idiomatic: "The customs of the empire today value wealth and slight righteousness, delight in pleasure and display, exalt extravagance, thin kinship ties, exalt marriage factions, join hastily and seek lucky breaks, and set up profit for themselves;" },
  { zh: "不改其原，雖歲赦之，刑猶難使錯而不用也，臣愚以為宜壹曠然大變其俗。", literal: "if their root is not changed, though amnestied every year, punishments still can hardly make errors unused; your subject foolishly thinks one ought with unified breadth greatly to transform their customs.", idiomatic: "and unless the root is changed, even yearly amnesties will not make punishments fall idle. Your subject foolishly thinks the customs ought to be transformed all at once and on a grand scale." },
  { zh: "夫朝廷者，天下之楨幹也。", literal: "Now the court is the main pillar of All-under-Heaven.", idiomatic: "The court is the main pillar of the empire." },
  { zh: "朝有變色之言，則下有爭鬥之患；", literal: "If at court there are words that change countenance, then below there is the trouble of contention and fighting;", idiomatic: "If at court there are words that change men's faces, below there will be strife;" },
  { zh: "上有自專之士，則下有不讓之人；", literal: "if above there are self-willed scholars, then below there are men who do not yield;", idiomatic: "if above there are self-willed men, below there will be men who refuse to yield;" },
  { zh: "上有克勝之佐，則下有傷害之心；", literal: "if above there are assistants who overcome and triumph, then below there are hearts that injure and harm;", idiomatic: "if above there are assistants who love to overcome others, below there will be hearts bent on injury;" },
  { zh: "上有好利之臣，則下有盜竊之民；", literal: "if above there are ministers who love profit, then below there are people who steal and rob;", idiomatic: "if above there are ministers who love profit, below there will be thieves among the people;" },
  { zh: "此其本也。", literal: "this is its root.", idiomatic: "that is the root of it." },
  { zh: "治天下者，審所上而已。", literal: "He who governs All-under-Heaven need only examine whom he elevates.", idiomatic: "He who governs the empire need only examine whom he elevates." },
  { zh: "教化之流，非家至而人說之也；", literal: "The flow of transforming instruction is not reaching every house and having people speak it;", idiomatic: "The flow of transforming instruction does not come from visiting every house and preaching to each person;" },
  { zh: "賢者在位，能者布職，朝廷崇禮，百僚敬讓，道德之行，由內及外，自近者始，然後民知所法，遷善日進而不自知也。", literal: "the worthy are in position, the able spread their duties, the court honors ritual, the hundred officials are respectful and yielding, the practice of virtue proceeds from within to without, beginning with what is near—only then do the people know what to take as law, move toward good daily advancing without themselves knowing it.", idiomatic: "the worthy hold office, the able perform their duties, the court honors ritual, the hundred officials are respectful and yielding, and the practice of virtue spreads from within outward, beginning with what is near—only then do the people know what to follow, advance toward good daily, and do so without even knowing it." },
  { zh: "《詩》曰：『商邑翼翼，四方之極。", literal: "The Odes says: 'The Shang capital is solemn and strong, the utmost of the four quarters.", idiomatic: "The Odes says, \"The Shang capital stands solemn and strong, the model for the four quarters.\"" },
  { zh: "』今長安，天子之都，親承聖化，然其習俗無以異於遠方，郡國來者無所法則，或見侈靡而放效之；", literal: "' Now Chang'an, the Son of Heaven's capital, personally receives sage transformation—yet its customs are no different from distant regions; those who come from commanderies and kingdoms have no model to follow, or they see extravagance and imitate it;", idiomatic: "\" Yet Chang'an, the Son of Heaven's capital, personally receives sage transformation, yet its customs are no different from distant regions. Visitors from the commanderies and kingdoms find no model to follow, or they see extravagance and imitate it;" },
  { zh: "此教化之原本，風俗之樞機，宜先正者也。", literal: "this is the root origin of transforming instruction, the pivot of customs—what ought first be rectified.", idiomatic: "this is the root of transforming instruction and the pivot of custom—what ought to be rectified first." },
  { zh: "臣聞天人之際，精祲有以相蕩，善惡有以相推，事作乎下者象動乎上，陰變則靜者動，陽蔽則明者晻，水旱之災隨類而至。", literal: "Your subject has heard that between Heaven and man, essences and vapors have means to stir each other; good and evil have means to push each other; affairs arising below are mirrored in movement above—when yin changes, what was still moves; when yang is blocked, what was bright grows dim; flood and drought disasters arrive according to their kinds.", idiomatic: "Your subject has heard that between Heaven and man essences and vapors stir one another, good and evil push one another, and affairs arising below are mirrored in movement above—when yin shifts, what was still moves; when yang is blocked, what was bright grows dim; flood and drought follow in their kinds." },
  { zh: "陛下祗畏天戒，哀閔元元，宜省靡麗，考制度，近忠正，遠巧佞，以崇至仁，匡失俗，道德弘於京師，淑問揚乎疆外，然後大化可成，禮讓可興也。", literal: "Your Majesty reverently fears Heaven's warnings, pities and commiserates with the black-haired people—you ought to reduce extravagance and splendor, examine institutions, draw near the loyal and upright, send far the crafty and sycophantic, thereby to exalt utmost benevolence and correct failing customs; when virtue and the Way are magnified in the capital and good report spreads beyond the borders, then great transformation can be achieved and courtesy and yielding can be raised.", idiomatic: "Your Majesty reverently heeds Heaven's warnings and pities the common people. You ought to reduce extravagance, examine institutions, draw near the loyal and upright, send away the crafty and sycophantic, exalt utmost benevolence, and correct failing customs. When virtue is magnified in the capital and good report spreads beyond the borders, then great transformation can be achieved and courtesy and yielding can flourish." },
  { zh: "」上說其言，遷衡為光祿大夫。", literal: "\" The emperor was pleased with his words and transferred Heng to be Grand Master of the Palace.", idiomatic: "\" The emperor was pleased with his words and transferred Heng to Grand Master of the Palace." },
  { zh: ":荀悅論曰：夫赦者，權時之宜，非常典也。", literal: ": Xun Yue's discussion says: Now amnesty is a timely expedient, not a constant statute.", idiomatic: ": Xun Yue's discussion says: Amnesty is a timely expedient, not a standing institution." },
  { zh: "漢興，承秦兵革之後，大愚之世，比屋可刑，故設三章之法，大赦之令，蕩滌穢流，與民更始，時勢然也。", literal: "When Han arose, inheriting after Qin's arms and armor, in an age of great ignorance where house by house could be punished, therefore the law of three chapters was established and the order of great amnesty—washing away foul currents and making a fresh start with the people; the times were so.", idiomatic: "When Han arose, inheriting the aftermath of Qin's wars, in an age of great ignorance where almost every household could be punished, the law of three chapters and orders of great amnesty were established to wash away foul currents and make a fresh start with the people—the times required it." },
  { zh: "後世承業，襲而不革，失時宜矣。", literal: "Later generations inherited the enterprise and followed without reform—losing the timely fit.", idiomatic: "Later generations inherited the practice and followed it without reform—missing the timely fit." },
  { zh: "若惠、文之世，無所赦之。", literal: "In ages such as those of Emperor Hui and Emperor Wen, there was nothing to amnesty.", idiomatic: "In ages such as those of Emperors Hui and Wen, there was nothing to amnesty." },
  { zh: "若孝景之時，七國皆亂，異心並起，奸詐非一；", literal: "In the time of Emperor Xiaojing, the seven states all rebelled, divergent hearts arose together, treachery and deceit were not one alone;", idiomatic: "In the time of Emperor Xiaojing the seven states all rebelled, divergent hearts arose together, and treachery was manifold;" },
  { zh: "及武帝末年，賦役繁興，群盜並起，加以太子之事，巫蠱之禍，天下紛然，百姓無聊，人不自安；", literal: "and by the late years of Emperor Wu, levies and corvée flourished, bandit gangs arose together, added to the affair of the heir apparent and the disaster of witchcraft—All-under-Heaven was in turmoil, the common people had no relief, men could not find security in themselves;", idiomatic: "and by the late years of Emperor Wu levies and corvée multiplied, bandit gangs arose together, and there were added the affair of the heir apparent and the disaster of witchcraft—All-under-Heaven was in turmoil, the people had no relief, and no one felt secure;" },
  { zh: "及光武之際，撥亂之後：如此之比，宜為赦矣。", literal: "and at the time of Emperor Guangwu, after settling disorder—cases like these ought to have amnesty.", idiomatic: "and at the time of Emperor Guangwu, after settling disorder—times like these called for amnesty." },
  { zh: "----6秋，七月，隴西羌彡姐旁種反，詔召丞相韋玄成等入議。", literal: "----6 Autumn, seventh month, the Qiang of the Shan-jie collateral lineage in Longxi rebelled; an edict summoned Chancellor Wei Xuancheng and others to enter for deliberation.", idiomatic: "----6 In autumn, the seventh month, the Qiang of the Shan-jie collateral lineage in Longxi rebelled; an edict summoned Chancellor Wei Xuancheng and others to deliberate." },
  { zh: "是時，歲比不登，朝廷方以為憂，而遭羌變，玄成等漠然，莫有對者。", literal: "At this time, year after year harvests did not succeed; the court was just taking it as worry, yet encountered the Qiang disturbance—Xuancheng and the others were blank, none having a reply.", idiomatic: "At this time harvests had failed year after year and the court was already worried when the Qiang disturbance struck. Xuancheng and the others sat blankly, with no one able to reply." },
  { zh: "右將軍馮奉世曰：「羌虜近在竟內背畔，不以時誅，無以威制遠蠻，臣願帥師討之！", literal: "General of the Right Feng Fengshi said: \"The Qiang barbarians are near, rebelling within the frontier—if not executed in season, there is no means to awe and control distant barbarians; your subject wishes to lead troops to punish them!", idiomatic: "General of the Right Feng Fengshi said, \"The Qiang are near at hand, rebelling within the frontier. If they are not punished promptly, there is no way to awe distant barbarians. Your subject wishes to lead troops to punish them!\"" },
  { zh: "」上問用兵之數，對曰：「臣聞善用兵者，役不再興，糧不三載，故師不久暴而天誅亟決。", literal: "\" The emperor asked the numbers for employing troops; he replied: \"Your subject has heard that one who skillfully uses troops does not raise corvée twice or transport grain three times; therefore armies do not long rage abroad while Heaven's punishment is swiftly decided.", idiomatic: "\" The emperor asked how many troops would be needed. He replied, \"Your subject has heard that one who skillfully uses troops does not raise corvée twice or transport grain three times. Therefore armies should not long rage abroad while Heaven's punishment is swiftly decided.\"" },
  { zh: "往者數不料敵，而師至於折傷，再三發調，則曠日煩費，威武虧矣。", literal: "In the past, several times the enemy was not measured and armies came to broken injury; repeatedly issuing levies then wastes days and troubles expense, and martial prestige is diminished.", idiomatic: "In the past we several times misjudged the enemy and armies were broken. Repeated levies waste time and money and diminish martial prestige." },
  { zh: "今反虜無慮三萬人，法當倍，用六萬人。", literal: "Now the rebel barbarians are estimated at no less than thirty thousand men; by rule one ought to double and employ sixty thousand.", idiomatic: "Now the rebels are estimated at no less than thirty thousand men. By rule one ought to double that and employ sixty thousand." },
  { zh: "然羌戎，弓矛之兵耳，器不犀利，可用四萬人。", literal: "Yet the Qiang and Rong are only bow-and-spear troops; their weapons are not sharp and keen—forty thousand can be employed.", idiomatic: "Yet the Qiang and Rong are only bow-and-spear fighters; their weapons are not sharp—forty thousand should suffice." },
  { zh: "一月足以決。", literal: "One month is sufficient to decide it.", idiomatic: "One month should be enough to settle it." },
  { zh: "」丞相、御史、兩將軍皆以為：「民方收斂時未可多發，發萬人屯守之，且足。", literal: "\" The chancellor, censor, and both generals all held: \"The people are just at harvest time and cannot be levied in great numbers; send ten thousand to garrison and defend—that will suffice for now.", idiomatic: "\" The chancellor, censor, and both generals all held, \"The people are just at harvest time and cannot be levied in great numbers. Send ten thousand to garrison the frontier—that will suffice for now.\"" },
  { zh: "」奉世曰：「不可。", literal: "\" Fengshi said: \"It cannot be done.", idiomatic: "\" Fengshi said, \"That will not do.\"" },
  { zh: "天下被饑饉，士馬羸耗，守戰之備久廢不簡，夷狄有輕邊吏之心，而羌首難。", literal: "All-under-Heaven suffers famine; soldiers and horses are emaciated and spent; preparations for defense and battle have long been abandoned and not examined; the Yi and Di have hearts that slight frontier officials—and the Qiang are foremost in difficulty.", idiomatic: "The empire suffers famine; soldiers and horses are worn down; defenses have long been neglected; the barbarians already look down on frontier officials—and the Qiang are the hardest of them." },
  { zh: "今以萬人分屯數處，虜見兵少，必不畏懼。", literal: "Now with ten thousand divided and garrisoned in several places, when the barbarians see few troops they will surely not fear.", idiomatic: "If ten thousand are divided and garrisoned in several places, the enemy will see how few the troops are and surely will not fear them." },
  { zh: "戰則挫兵病師，守則百姓不救，如此，怯弱之形見。", literal: "If they fight, troops are broken and armies fall ill; if they defend, the common people are not rescued—thus the form of timidity and weakness appears.", idiomatic: "If they fight, the army will be broken; if they only defend, the people cannot be rescued. In that way weakness will be plain for all to see." },
  { zh: "羌人乘利，諸種並和，相扇而起，臣恐中國之役不得止於四萬，非財幣所能解也。", literal: "The Qiang will seize the advantage; the various tribes will join in harmony, fanning one another to rise; your subject fears the empire's campaign will not stop at forty thousand, and it cannot be resolved by wealth and currency alone.", idiomatic: "The Qiang will seize the advantage, the various tribes will join together and fan one another into revolt. Your subject fears the empire's campaign will not stop at forty thousand men, and money alone cannot solve it." },
  { zh: "故少發師而曠日，與一舉而疾決，利害相萬也。", literal: "Therefore to send few troops and waste days, versus one effort and swift decision—the benefit and harm differ ten thousandfold.", idiomatic: "Therefore to send few troops and waste days, versus one effort and swift decision—the difference in benefit and harm is ten thousandfold." },
  { zh: "」固爭之，不能得。", literal: "\" He firmly contended but could not obtain it.", idiomatic: "\" He argued firmly but could not prevail." },
  { zh: "有詔，益二千人。", literal: "An edict was issued increasing by two thousand men.", idiomatic: "An edict was issued to add two thousand men." },
  { zh: "於是遣奉世將萬二千人騎，以將屯為名，典屬國任立、護軍都尉韓昌為偏裨，到隴西，分屯三處。", literal: "Thereupon Fengshi was sent leading twelve thousand cavalry, under the name of a garrison commandant, with Director of Dependent States Ren Li and Protector Army Commandant Han Chang as flank assistants; they reached Longxi and divided garrisons in three places.", idiomatic: "Thereupon Fengshi was sent leading twelve thousand cavalry under the title of garrison commandant, with Director of Dependent States Ren Li and Protector Army Commandant Han Chang as flank assistants. They reached Longxi and divided garrisons in three places." },
  { zh: "昌先遣兩校尉與羌戰，羌虜盛多，皆為所破，殺兩校尉。", literal: "Han Chang first sent two commandants to fight the Qiang; the Qiang barbarians were numerous and strong, and both were broken by them—the two commandants were killed.", idiomatic: "Han Chang first sent two commandants to fight the Qiang. The enemy were numerous and strong, both units were defeated, and the two commandants were killed." },
  { zh: "奉世具上地形部眾多少之計，願益三萬六千人，乃足以決事。", literal: "Fengshi fully reported up a plan of terrain and numbers of divisions and masses, wishing to add thirty-six thousand men—only then would it suffice to decide the affair.", idiomatic: "Fengshi reported in full on the terrain and troop strength and asked for thirty-six thousand more men, saying only then would the affair be settled." },
  { zh: "書奏，天子大為發兵六萬餘人。", literal: "When the memorial was submitted, the Son of Heaven greatly raised troops of more than sixty thousand men.", idiomatic: "When the memorial arrived, the emperor greatly raised an army of more than sixty thousand men." },
  { zh: "八月，拜太常弋陽侯任千秋為奮武將軍以助之。", literal: "In the eighth month, Ren Qianqiu, Marquis of Yiyang and Grand Master of Ceremonies, was appointed General Who Displays Martial Might to assist him.", idiomatic: "In the eighth month Ren Qianqiu, Marquis of Yiyang and Grand Master of Ceremonies, was appointed General Who Displays Martial Might to assist him." },
  { zh: "冬，十月，兵畢至隴西，十一月，並進，羌虜大破，斬首數千級，餘皆走出塞。", literal: "In winter, the tenth month, the troops all arrived at Longxi; in the eleventh month they advanced together. The Qiang barbarians were greatly defeated; heads cut numbered several thousand; the remainder all fled out beyond the frontier passes.", idiomatic: "In winter, the tenth month, the troops all reached Longxi; in the eleventh month they advanced together. The Qiang were routed, several thousand heads were taken, and the rest all fled beyond the frontier." },
  { zh: "兵未決間，漢復發募士萬人，拜定襄太守韓安國為建威將軍，未進，聞羌破而還。", literal: "While the campaign was not yet decided, Han again raised and recruited ten thousand men, appointing Han Anguo, Administrator of Dingxiang, as General Who Establishes Might. He had not advanced when he heard the Qiang were broken and returned.", idiomatic: "While the campaign was still undecided, Han again recruited ten thousand men and appointed Han Anguo, Administrator of Dingxiang, as General Who Establishes Might. He had not advanced when he heard the Qiang were defeated and returned." },
  { zh: "詔罷吏士，頗留屯田，備要害處。", literal: "An edict dismissed officers and soldiers, but many were left for garrison-farming to guard strategic points.", idiomatic: "An edict dismissed the officers and soldiers, but many were left to garrison-farm and guard strategic points." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
